-- KITAPVERSE — Quest seed/link for existing library books
-- Source: uploaded grade 6, 7, 8 quest documents and 9–10 quiz document.
-- 120 books/quests, 5 questions each = 600 questions.
-- This script DOES NOT create duplicate library books. It finds existing library_books by grade + title,
-- creates/refreshes one quest per matched book, links library_books.quest_id, and leaves unmatched books untouched.
-- Re-running the script is safe: existing generated quests for the same book are refreshed.

create or replace function public.kv_norm_title(p text)
returns text language sql immutable as $$
  select lower(regexp_replace(trim(coalesce(p,'')), '\s+', ' ', 'g'));
$$;

DO $$
declare
  r jsonb; q jsonb; v_book_id bigint; v_quest_id bigint; v_existing bigint;
  v_title text; v_grade int; v_author text; v_desc text;
  v_key text; v_alias text;
begin
  for r in select value from jsonb_array_elements($data$[{"grade": 6, "n": 1, "title": "Менің атым Қожа", "author": "Бердібек Соқпақбаев", "questions": [{"n": 1, "question": "Қожа кітапта қандай жерде — қалада ма, әлде ауылда ма — өмір сүреді?", "opts": {"a": "Үлкен қалада", "b": "Ауылда", "c": "Теңіз жағасында", "d": "Тау басындағы шатқалда"}, "correct": "b"}, {"n": 2, "question": "Шығарма негізінен қандай сипатта жазылған?", "opts": {"a": "Қорқыныш романы", "b": "Балалық шақ туралы жартылай өмірбаяндық, әзіл-күлкіге толы повесть", "c": "Ғылыми-фантастикалық хикая", "d": "Тарихи-соғыс романы"}, "correct": "b"}, {"n": 3, "question": "Қожаның мінез-құлқы бойынша ол қандай бала?", "opts": {"a": "Тым momын, ешқашан ерсілік жасамайтын", "b": "Ойыншы, тентек, талай жаманатты оқиғаға тап болатын", "c": "Спортшы, тек футболмен айналысатын", "d": "Мектепке мүлде бармайтын"}, "correct": "b"}, {"n": 4, "question": "Повестегі оқиғалар негізінен қай кезеңдегі қазақ ауылының өмірін суреттейді?", "opts": {"a": "Қазіргі заман", "b": "20 ғасырдың басы — Кеңес дәуірінің алғашқы жылдары", "c": "Хандық дәуір", "d": "Тәуелсіздік алғаннан кейінгі жылдар"}, "correct": "b"}, {"n": 5, "question": "Автор Бердібек Соқпақбаев бұл шығарманы негізінен неге арнаған?", "opts": {"a": "Тек тарихи оқиғаларды баяндауға", "b": "Өз балалық шағының естеліктеріне сүйеніп жазуға", "c": "Шетел әдебиетінен аударуға", "d": "Ғылыми зерттеу жүргізуге"}, "correct": "b"}]}, {"grade": 6, "n": 2, "title": "Көксерек", "author": "Мұхтар Әуезов", "questions": [{"n": 1, "question": "«Көксерек» шығармасында бас кейіпкер бала кімді асырап алады?", "opts": {"a": "Түлкі балаcын", "b": "Қасқыр балаcын (бөлтірікті)", "c": "Аюдың балаcын", "d": "Жолбарыс балаcын"}, "correct": "b"}, {"n": 2, "question": "Балалық шағында үй жануары ретінде өскен қасқыр ақыр аяғында қалай аяқталады?", "opts": {"a": "Иесіне мәңгі берілген үй жануары болып қалады", "b": "Табиғи инстинкті басым түсіп, қайтадан жыртқыш аңға айналады", "c": "Ауылдан тыныш кетіп қалады", "d": "Аңшылар оны құтқарып, орманға жібереді"}, "correct": "b"}, {"n": 3, "question": "Шығармада көтерілетін басты идея — не туралы?", "opts": {"a": "Табиғи болмысты (инстинктті) тәрбиемен өзгерту мүмкін емес екені", "b": "Қасқырлар қашанда адалдыққа берілген", "c": "Ауыл балаларының ойын-сауығы", "d": "Аңшылықтың пайдасы"}, "correct": "a"}, {"n": 4, "question": "Автор Мұхтар Әуезов қазақ әдебиетінде негізінен қандай жазушы ретінде танымал?", "opts": {"a": "Тек ақын ретінде", "b": "Ұлы жазушы, драматург, «Абай жолы» эпопеясының авторы", "c": "Тек аудармашы ретінде", "d": "Тек тарихшы ретінде"}, "correct": "b"}, {"n": 5, "question": "«Көксерек» оқиғасы қай ортада — қандай кәсіппен айналысатын адамдар арасында өтеді?", "opts": {"a": "Балықшылар арасында", "b": "Мал шаруашылығымен айналысатын ауыл адамдары арасында", "c": "Кеншілер арасында", "d": "Теңізшілер арасында"}, "correct": "b"}]}, {"grade": 6, "n": 3, "title": "Қажымұқан", "author": "Қалмақан Әбдіқадыров", "questions": [{"n": 1, "question": "Хикаят қандай нақты, тарихта болған тұлғаның өмірін баяндайды?", "opts": {"a": "Ойдан шығарылған палуан туралы", "b": "Дүниежүзі чемпионы, атақты қазақ балуаны Қажымұқан Мұңайтпасовтың өмірін", "c": "Хан туралы", "d": "Ақынның өмірін"}, "correct": "b"}, {"n": 2, "question": "Қажымұқан қандай спорт түрінен әлемдік деңгейде танылды?", "opts": {"a": "Классикалық күрес (балуандық)", "b": "Футбол", "c": "Шахмат", "d": "Атыс спорты"}, "correct": "a"}, {"n": 3, "question": "Хикаятта Қажымұқан қандай отбасыдан шыққан бала ретінде суреттеледі?", "opts": {"a": "Өте бай әрі дәулетті отбасынан", "b": "Кедей, қиыншылықпен өскен отбасынан", "c": "Хан әулетінен", "d": "Саудагер отбасынан"}, "correct": "b"}, {"n": 4, "question": "Қажымұқан қанша жыл бойы «Орыс балуан» атанып, талай патшалықтың жерін аралаған?", "opts": {"a": "Бір жыл", "b": "Он екі жыл", "c": "Отыз жыл", "d": "Алты ай"}, "correct": "b"}, {"n": 5, "question": "Автор Қалмақан Әбдіқадыров бұл шығармасында негізгі кейіпкерді қалай сипаттайды?", "opts": {"a": "Тек дене күшімен ерекшеленетін адам ретінде ғана", "b": "Ерлігі мен адамгершілігі қатар ұштасқан ұлт намысын қорғаған тұлға ретінде", "c": "Мансапқор адам ретінде", "d": "Қорқақ адам ретінде"}, "correct": "b"}]}, {"grade": 6, "n": 4, "title": "Мейірімді Асқар", "author": "Баянғали Әлімжанов", "questions": [{"n": 1, "question": "Ертегінің басында Асқар қария бір ғажайып оқиғадан соң кімге айналады?", "opts": {"a": "Патшаға", "b": "Кішкентай балаға", "c": "Құсқа", "d": "Батырға"}, "correct": "b"}, {"n": 2, "question": "Асқар ертегі әлемінде саяхаттап жүріп қай әйгілі қазақ ертегі кейіпкерімен алдымен танысады (кемпеске/қулықпен танылған)?", "opts": {"a": "Алдар көсемен", "b": "Ер Төстікпен", "c": "Қобыланды батырмен", "d": "Алпамыс батырмен"}, "correct": "a"}, {"n": 3, "question": "Ертегінің екінші бөлімінде Асқар қандай кейіпкерлермен дос болады?", "opts": {"a": "Батырлар мен хандармен", "b": "Таусоғар, Желаяқ, Көлтаусар, Епті сияқты ертегі кейіпкерлерімен", "c": "Ғарышкерлермен", "d": "Теңіз құбыжықтарымен"}, "correct": "b"}, {"n": 4, "question": "Үшінші бөлімде («Мейірімді Асқар мен момын төлдер») Асқар кімдерден мал төлдерін құтқарады?", "opts": {"a": "Жезтырнақ пен Жалмауыз кемпірден", "b": "Айдаһардан", "c": "Қарақшылардан", "d": "Суда батудан"}, "correct": "a"}, {"n": 5, "question": "Ертегі негізінен қандай құндылықты дәріптейді?", "opts": {"a": "Тек күш пен қаруды", "b": "Мейірімділік пен ақ пейілдің арқасында достық табу", "c": "Байлыққа ұмтылуды", "d": "Жалғыздықты"}, "correct": "b"}]}, {"grade": 6, "n": 5, "title": "Көшім бала", "author": "Жәнібек Кәрменов", "questions": [{"n": 1, "question": "Шығарманың бас кейіпкері кім деп аталады?", "opts": {"a": "Көшім", "b": "Әсет", "c": "Дархан", "d": "Нұрлан"}, "correct": "a"}, {"n": 2, "question": "Шығарма авторы Жәнібек Кәрменов қандай жанрда көбіне жазады?", "opts": {"a": "Ғылыми-фантастика", "b": "Балаларға арналған көркем әдебиет / повесть-әңгіме", "c": "Драма пьесалары", "d": "Тарихи роман"}, "correct": "b"}, {"n": 3, "question": "Кітап атауындағы «бала» сөзі көрсетіп тұрғандай, шығарма кімнің көзқарасы арқылы баяндалады?", "opts": {"a": "Кәрі шаманың", "b": "Жас балалы қаhарманның", "c": "Аңшының", "d": "Ханшайымның"}, "correct": "b"}, {"n": 4, "question": "Мұндай шығармаларда әдетте қандай тақырып көтеріледі?", "opts": {"a": "Ғарышты игеру", "b": "Бала мен ортаның (ауыл/отбасы) қарым-қатынасы, өсу жолы", "c": "Соғыс тарихы", "d": "Су асты дүниесі"}, "correct": "b"}, {"n": 5, "question": "Кітапты оқығаннан кейін нақты қандай оқиға желісін білуге болады?", "opts": {"a": "Тек кітаптың атауын", "b": "Көшімнің басынан кешкен нақты оқиғалар тізбегін", "c": "Тек авторының туған жылын", "d": "Тек басылым жылын"}, "correct": "b"}]}, {"grade": 6, "n": 6, "title": "Алтын тостағанды іздеу", "author": "Зира Наурызбаева, Лиля Калаус", "questions": [{"n": 1, "question": "Кітаптың бас кейіпкері — қандай есімді бала?", "opts": {"a": "Бату", "b": "Асан", "c": "Ерлан", "d": "Дархан"}, "correct": "a"}, {"n": 2, "question": "Бату және достары не іздейді?", "opts": {"a": "Жоғалған алтын тостағанды", "b": "Жасырын қазынаны", "c": "Ежелгі қаруды", "d": "Сиқырлы кітапты"}, "correct": "a"}, {"n": 3, "question": "Кітап қандай тақырыпты қазақ фольклорымен ұштастырады?", "opts": {"a": "Тек заманауи технологияны", "b": "Шытырман оқиғалы саяхат пен қазақ мифологиясының кейіпкерлерін", "c": "Тек тарихи шындықты", "d": "Тек ғылыми деректерді"}, "correct": "b"}, {"n": 4, "question": "Авторлар Зира Наурызбаева мен Лиля Калаус бірлесіп қандай сериялы кітап жаза бастады?", "opts": {"a": "Бату мен оның достары туралы балалар сериясын", "b": "Ересектерге арналған детектив сериясын", "c": "Ғылыми оқулықтар сериясын", "d": "Өлеңдер жинағын"}, "correct": "a"}, {"n": 5, "question": "Шығарма қандай жанрға жатады?", "opts": {"a": "Тарихи құжаттама", "b": "Шытырман оқиғалы фэнтези/приключение", "c": "Ғылыми монография", "d": "Драма пьесасы"}, "correct": "b"}]}, {"grade": 6, "n": 7, "title": "Робинзон Крузо", "author": "Даниель Дефо", "questions": [{"n": 1, "question": "Робинзон Крузо қандай оқиғадан кейін аралда жалғыз қалады?", "opts": {"a": "Ұшақ апатынан кейін", "b": "Кеме апатынан (борандан) кейін", "c": "Соғыстан кейін", "d": "Ұрланғаннан кейін"}, "correct": "b"}, {"n": 2, "question": "Робинзон аралда жалғыз болғанда алдымен нені қамтамасыз етуге тырысады?", "opts": {"a": "Достар табу", "b": "Тамақ, баспана және қауіпсіздік", "c": "Байлық жинау", "d": "Кеме жасау"}, "correct": "b"}, {"n": 3, "question": "Робинзон аралда ұзақ жылдар бойы кездестірген жергілікті тұрғынды қалай атайды?", "opts": {"a": "Пятница (Жұма)", "b": "Понедельник", "c": "Воскресенье", "d": "Сенбі"}, "correct": "a"}, {"n": 4, "question": "Робинзон аралда қанша жылдай өмір сүреді (шамамен)?", "opts": {"a": "Бір-екі жыл", "b": "Жиырма шақты жыл", "c": "Жүз жыл", "d": "Алты ай"}, "correct": "b"}, {"n": 5, "question": "Роман негізінен қандай тақырыпты дәріптейді?", "opts": {"a": "Байлыққа құмарлықты", "b": "Адамның төзімділігі мен табиғатпен күресте аман қалуын", "c": "Соғыс қаталдығын", "d": "Ғашықтық драмасын"}, "correct": "b"}]}, {"grade": 6, "n": 8, "title": "Әлемді 80 күн ішінде шарлау", "author": "Жюль Верн", "questions": [{"n": 1, "question": "Бас кейіпкер Филеас Фогг әлемді неше күнде аралап шығуға бәстеседі?", "opts": {"a": "30 күнде", "b": "80 күнде", "c": "100 күнде", "d": "365 күнде"}, "correct": "b"}, {"n": 2, "question": "Фоггтың адал қызметшісінің есімі кім?", "opts": {"a": "Паспарту", "b": "Ватсон", "c": "Санчо", "d": "Фигаро"}, "correct": "a"}, {"n": 3, "question": "Фогг бәсті неге ұтылмауы керек еді?", "opts": {"a": "Достарымен клубта бәстескені үшін, намыс үшін", "b": "Жарысқа қатысу үшін", "c": "Патшаға сый үшін", "d": "Ешбір себепсіз"}, "correct": "a"}, {"n": 4, "question": "Саяхат барысында олар негізінен қандай көлік түрлерін қолданады?", "opts": {"a": "Тек жаяу жүру", "b": "Кеме, теміржол, пойыз, тіпті піл сияқты әртүрлі көлік", "c": "Тек ат", "d": "Тек велосипед"}, "correct": "b"}, {"n": 5, "question": "Роман авторы Жюль Верн негізінен қандай жанрдың атасы саналады?", "opts": {"a": "Ғылыми фантастика мен саяхат романдарының", "b": "Детектив жанрының", "c": "Комедия жанрының", "d": "Тарихи роман жанрының"}, "correct": "a"}]}, {"grade": 6, "n": 9, "title": "Бала Мәжиттің хикаялары", "author": "Хушанг Муради Кермани", "questions": [{"n": 1, "question": "Шығарманың бас кейіпкері Мәжитті кім тәрбиелейді?", "opts": {"a": "Ата-анасы", "b": "Әжесі", "c": "Мұғалімі", "d": "Ағасы"}, "correct": "b"}, {"n": 2, "question": "Хикаялар қай елдің өмірінен алынған (автор қай елдің жазушысы)?", "opts": {"a": "Қазақстанның", "b": "Иранның", "c": "Түркияның", "d": "Қытайдың"}, "correct": "b"}, {"n": 3, "question": "Шығарма жанры бойынша негізінен қандай сипатта жазылған?", "opts": {"a": "Қорқыныш хикая", "b": "Күнделікті тұрмыс туралы жылы, әзілі мол әңгімелер топтамасы", "c": "Ғылыми-фантастика", "d": "Соғыс драмасы"}, "correct": "b"}, {"n": 4, "question": "Мәжиттің басынан өткен оқиғалар негізінен қайда болып жатады?", "opts": {"a": "Ғарышта", "b": "Оның өз ауылы/қаласындағы күнделікті өмірде", "c": "Теңіз түбінде", "d": "Басқа планетада"}, "correct": "b"}, {"n": 5, "question": "Мұндай хикаялар балаларға негізінен нені үйретуге бағытталған?", "opts": {"a": "Тек тарихи фактілерді жаттауды", "b": "Қиындықтарға қарамастан өмірге деген жылы көзқарас пен әзіл сезімін сақтауды", "c": "Спорттық жаттығуларды", "d": "Компьютерлік дағдыларды"}, "correct": "b"}]}, {"grade": 6, "n": 10, "title": "Хәрри Поттер және пәлсапа тасы", "author": "Джоан Роулинг", "questions": [{"n": 1, "question": "Гарри Поттер қай мектепте оқуға түседі?", "opts": {"a": "Хогвартс сиқыршылар мектебі", "b": "Итон колледжі", "c": "Кембридж университеті", "d": "Оксфорд мектебі"}, "correct": "a"}, {"n": 2, "question": "Гарридің ерекшелігі — маңдайында қандай белгі бар?", "opts": {"a": "Жұлдыз тәрізді белгі", "b": "Найзағай тәрізді тыртық", "c": "Айдай белгі", "d": "Ешбір белгі жоқ"}, "correct": "b"}, {"n": 3, "question": "Гарридің ең жақын екі досының есімдері кім?", "opts": {"a": "Рон Уизли мен Гермиона Грейнджер", "b": "Драко мен Люциус", "c": "Дадли мен Петуния", "d": "Сириус пен Люпин"}, "correct": "a"}, {"n": 4, "question": "Кітаптағы басты жауыз кейіпкердің есімі кім?", "opts": {"a": "Дамблдор", "b": "Волдеморт", "c": "Хагрид", "d": "Снейп"}, "correct": "b"}, {"n": 5, "question": "«Пәлсапа тасы» кітапта қандай қасиетімен ерекшеленеді?", "opts": {"a": "Ұшуға мүмкіндік береді", "b": "Мәңгілік өмір сүруге және кез келген затты алтынға айналдыруға көмектеседі", "c": "Уақытты бақылауға мүмкіндік береді", "d": "Ешбір қасиеті жоқ"}, "correct": "b"}]}, {"grade": 6, "n": 11, "title": "Қаныштың жастақ шағы", "author": "Төкен Оразов", "questions": [{"n": 1, "question": "Кітап қазақтың атақты ғалымы, геолог-академигі Қанышты — толық атымен кімді айтады?", "opts": {"a": "Қаныш Сәтбаевты", "b": "Қаныш Иманбаевты", "c": "Қаныш Байтұрсынұлын", "d": "Қаныш Жұбановты"}, "correct": "a"}, {"n": 2, "question": "Шығарма Қанышты өмірінің қай кезеңінде — есейгенде ме, әлде жас/бала кезінде бе — суреттейді?", "opts": {"a": "Кәрілік шағында", "b": "Жастық/бала кезінде", "c": "Тек өлген күнінде", "d": "Тек студент кезінде ғана"}, "correct": "b"}, {"n": 3, "question": "Қаныш Сәтбаев кейінірек қандай саладағы ғалым ретінде танымал болды?", "opts": {"a": "Медицина", "b": "Геология (жер қойнауын зерттеу)", "c": "Астрономия", "d": "Тіл білімі"}, "correct": "b"}, {"n": 4, "question": "Қаныш Сәтбаев есімімен байланысты қандай кен орны әйгілі?", "opts": {"a": "Жезқазған мыс кен орны", "b": "Теңіз түбіндегі мұнай кені", "c": "Алтын кені Балқашта", "d": "Көмір кені Қарағандыда ғана"}, "correct": "a"}, {"n": 5, "question": "Мұндай өмірбаяндық шығармалар оқырманға негізінен нені көрсетуге бағытталған?", "opts": {"a": "Тек тарихи датаны жаттауды", "b": "Ұлы адамдардың бала кезден еңбекқорлық пен ізденіске бейімділігін", "c": "Тек ғылыми терминдерді", "d": "Тек географиялық атауларды"}, "correct": "b"}]}, {"grade": 6, "n": 12, "title": "Жасампаз жасөспірімнің 7 дағдысы", "author": "Шон Кови", "questions": [{"n": 1, "question": "Кітап негізінен қандай жанрда жазылған?", "opts": {"a": "Көркем әңгіме", "b": "Жасөспірімдерге арналған өзін-өзі дамыту (мотивациялық) кітап", "c": "Ғылыми-фантастика романы", "d": "Тарихи хроника"}, "correct": "b"}, {"n": 2, "question": "Кітап авторы Шон Кови кімнің «7 дағды» идеясын жасөспірімдерге бейімдеп жазған?", "opts": {"a": "Өз әкесі Стивен Ковидің идеясын", "b": "Ешкімнің идеясын пайдаланбаған, толығымен жаңа", "c": "Дейл Карнегидің идеясын", "d": "Наполеон Хиллдің идеясын"}, "correct": "a"}, {"n": 3, "question": "Кітапта «Проактивті бол» дағдысы негізінен нені білдіреді?", "opts": {"a": "Тек күту, ешнәрсе істемеу", "b": "Жағдайларға жауап беруде өз таңдауыңды өзің жасау, бастамашыл болу", "c": "Басқалардың айтқанын ғана орындау", "d": "Ешкіммен санаспау"}, "correct": "b"}, {"n": 4, "question": "Кітап оқырманға негізінен қандай мақсатпен жазылған?", "opts": {"a": "Тек ойын-сауық үшін", "b": "Жасөспірімдерге өмірде табысты болуға көмектесетін тиімді әдеттерді үйрету", "c": "Тек тарихты үйрету", "d": "Тек тілдерді үйрету"}, "correct": "b"}, {"n": 5, "question": "«7 дағды» тұжырымдамасында дағдылардың неше тобы бар (жеке жеңіс, қоғамдық жеңіс)?", "opts": {"a": "Тек біреу", "b": "Екі негізгі топ (жеке және қоғамдық жеңістер)", "c": "Он топ", "d": "Топтарға бөлінбейді"}, "correct": "b"}]}, {"grade": 6, "n": 13, "title": "Кішкентай ханзада", "author": "Антуан де Сент-Экзюпери", "questions": [{"n": 1, "question": "Кішкентай ханзада қай планетадан келген?", "opts": {"a": "В-612 астероидынан", "b": "Марстан", "c": "Айдан", "d": "Жерден"}, "correct": "a"}, {"n": 2, "question": "Кішкентай ханзада өз планетасында қандай гүлді жақсы көреді және оны күтеді?", "opts": {"a": "Раушан гүлін", "b": "Күнбағысты", "c": "Тюльпанды", "d": "Лалагүлді"}, "correct": "a"}, {"n": 3, "question": "Хикаяны баяндайтын кейіпкер (пилот) кіммен Сахара шөлінде кездеседі?", "opts": {"a": "Кішкентай ханзадамен", "b": "Патшамен", "c": "Түлкімен ғана", "d": "Жыланмен ғана"}, "correct": "a"}, {"n": 4, "question": "Хикаяда түлкі Кішкентай ханзадаға достық туралы қандай маңызды сөз айтады («үйрету»)?", "opts": {"a": "«Достасу» деген «уайымдау»", "b": "«Үйрету» деген «баулу»", "c": "Ешнәрсе айтпайды", "d": "Тек ойнауды үйретеді"}, "correct": "b"}, {"n": 5, "question": "Хикаяның негізгі идеясы — көзге көрінбейтін нәрсенің маңызы туралы. Бұл қандай ой?", "opts": {"a": "Ең маңызды нәрселерді жүрекпен ғана көруге болады", "b": "Тек көзге көрінетін нәрсе бағалы", "c": "Ешнәрсенің мәні жоқ", "d": "Ойыншықтар ең маңызды"}, "correct": "a"}]}, {"grade": 6, "n": 14, "title": "Мұзтау", "author": "Оралхан Бокей", "questions": [{"n": 1, "question": "Повестің бас кейіпкері кім деп аталады?", "opts": {"a": "Ақтан", "b": "Серік", "c": "Дәурен", "d": "Болат"}, "correct": "a"}, {"n": 2, "question": "Ақтан балалық шағынан бері негізінен қандай малмен (аңмен) тығыз байланыста өседі?", "opts": {"a": "Жылқымен", "b": "Бұғылармен", "c": "Түйемен", "d": "Қойлармен"}, "correct": "b"}, {"n": 3, "question": "Ақтанның әкесі не болған, ол неге жалғыз қалды?", "opts": {"a": "Соғыстан оралмаған", "b": "Қалаға көшіп кетті", "c": "Ешқашан болмаған", "d": "Аңшылықта қаза тапты (басқа себеп)"}, "correct": "a"}, {"n": 4, "question": "Ауылды тастап кетпей, Ақтан қандай қызмет атқаруға кіріседі?", "opts": {"a": "Мұғалім болады", "b": "Ауыл күзетшісі болады", "c": "Дәрігер болады", "d": "Милиция болады"}, "correct": "b"}, {"n": 5, "question": "Повестегі қосымша желіде біреу үңгірде жасырылған нені іздейді?", "opts": {"a": "Жасырын қазынаны", "b": "Жоғалған малды", "c": "Ежелгі қолжазбаны", "d": "Су көзін"}, "correct": "a"}]}, {"grade": 6, "n": 15, "title": "Ауыл шетіндегі үй", "author": "Әкім Тарази", "questions": [{"n": 1, "question": "Бұл кітап негізінен қандай түрде жарық көрген — жалғыз үлкен роман ба, әлде әңгімелер жинағы ма?", "opts": {"a": "Жалғыз үлкен роман", "b": "Түрлі жылдары жазылған әңгімелер топтамасы", "c": "Өлеңдер жинағы", "d": "Ғылыми мақалалар жинағы"}, "correct": "b"}, {"n": 2, "question": "Автор Әкім Тарази қазақ әдебиетінде негізінен кім ретінде танымал?", "opts": {"a": "Белгілі жазушы, драматург, «Еңбек Ері» атанған қаламгер", "b": "Тек аудармашы", "c": "Тек журналист", "d": "Тек тарихшы"}, "correct": "a"}, {"n": 3, "question": "Жинақтың алғашқы әңгімесі «Жалын» журналының тұңғыш нөмірінде қандай атпен жарық көрген?", "opts": {"a": "«Ауыл шетіндегі үй»", "b": "«Әнім сен едіңнен»", "c": "«Соңғы сапар»", "d": "«Дала үні»"}, "correct": "b"}, {"n": 4, "question": "Шығармалар негізінен қандай ортадағы адамдардың тағдырын суреттейді?", "opts": {"a": "Қала тұрғындарының", "b": "Қазақ ауылының адамдары мен сол кездегі қоғам қайшылығын", "c": "Теңізшілердің", "d": "Ғарышкерлердің"}, "correct": "b"}, {"n": 5, "question": "Мұндай әңгімелер топтамасы оқырманға негізінен нені көрсетуге тырысады?", "opts": {"a": "Тек күлкілі жағдайларды", "b": "Уақыт таңбасы мен замана шындығын, адамдардың мінез-тағдырын", "c": "Тек ертегі әлемін", "d": "Тек ғылыми фактілерді"}, "correct": "b"}]}, {"grade": 6, "n": 16, "title": "Меня зовут Кожа", "author": "Бердибек Сокпакбаев", "questions": [{"n": 1, "question": "Где происходит действие повести — в городе или в ауле?", "opts": {"a": "В большом городе", "b": "В казахском ауле", "c": "На берегу моря", "d": "В горном ущелье"}, "correct": "b"}, {"n": 2, "question": "Каким по характеру мальчиком показан Кожа?", "opts": {"a": "Тихим и незаметным", "b": "Озорным, попадающим в разные смешные и не только истории", "c": "Взрослым не по годам серьёзным", "d": "Равнодушным ко всему"}, "correct": "b"}, {"n": 3, "question": "В каком жанре в основном написана повесть?", "opts": {"a": "Научная фантастика", "b": "Полуавтобиографическая повесть о детстве, с юмором", "c": "Детектив", "d": "Исторический роман о войне"}, "correct": "b"}, {"n": 4, "question": "Повесть в основном отражает жизнь казахского аула в какой период?", "opts": {"a": "В наши дни", "b": "В начале советской эпохи (первая половина XX века)", "c": "В ханский период", "d": "После обретения независимости"}, "correct": "b"}, {"n": 5, "question": "На чём во многом основан сюжет повести, судя по автобиографичности произведения?", "opts": {"a": "Полностью на вымысле, не связанном с автором", "b": "На собственных воспоминаниях автора о детстве", "c": "На переводе зарубежного романа", "d": "На научных исследованиях"}, "correct": "b"}]}, {"grade": 6, "n": 17, "title": "Серый Лютый", "author": "Мухтар Ауэзов", "questions": [{"n": 1, "question": "Кого приручает главный герой-мальчик в этой повести?", "opts": {"a": "Лисёнка", "b": "Волчонка", "c": "Медвежонка", "d": "Тигрёнка"}, "correct": "b"}, {"n": 2, "question": "Чем в итоге заканчивается попытка приручить дикого зверя?", "opts": {"a": "Зверь навсегда остаётся преданным домашним питомцем", "b": "В звере побеждает дикая природа, и он возвращается к хищничеству", "c": "Зверь погибает от болезни", "d": "Хозяин отпускает его в зоопарк"}, "correct": "b"}, {"n": 3, "question": "Какая главная идея заложена в повести?", "opts": {"a": "Дикую природу воспитанием изменить невозможно", "b": "Волки всегда преданы человеку", "c": "Охота — это весело", "d": "Аул живёт без животных"}, "correct": "a"}, {"n": 4, "question": "Чем знаменит автор Мухтар Ауэзов в казахской литературе?", "opts": {"a": "Только как переводчик", "b": "Как великий писатель, автор эпопеи «Путь Абая»", "c": "Только как поэт", "d": "Только как историк"}, "correct": "b"}, {"n": 5, "question": "В какой среде происходит действие повести?", "opts": {"a": "Среди рыбаков", "b": "Среди аульных жителей, занимающихся животноводством", "c": "Среди моряков", "d": "Среди горожан"}, "correct": "b"}]}, {"grade": 6, "n": 18, "title": "Приключения Бату и его друзей: в поисках золотой чаши", "author": "Зира Наурзбаева, Лиля Калаус", "questions": [{"n": 1, "question": "Как зовут главного героя книги — мальчика?", "opts": {"a": "Бату", "b": "Ержан", "c": "Дамир", "d": "Асхат"}, "correct": "a"}, {"n": 2, "question": "Что ищут Бату и его друзья на протяжении сюжета?", "opts": {"a": "Пропавшую золотую чашу", "b": "Клад пиратов", "c": "Волшебный меч", "d": "Затерянный город"}, "correct": "a"}, {"n": 3, "question": "На каком материале (фольклоре) во многом строится сюжет книги?", "opts": {"a": "На казахской мифологии и легендах", "b": "Только на греческих мифах", "c": "Только на современных технологиях", "d": "На научных фактах без вымысла"}, "correct": "a"}, {"n": 4, "question": "В каком жанре написана книга?", "opts": {"a": "Историческая документалистика", "b": "Приключенческое фэнтези для детей", "c": "Научный труд", "d": "Пьеса"}, "correct": "b"}, {"n": 5, "question": "Авторы Зира Наурзбаева и Лиля Калаус создали книгу как часть чего?", "opts": {"a": "Серии книг о Бату и его друзьях", "b": "Единственного произведения без продолжения", "c": "Учебника по истории", "d": "Сборника стихов"}, "correct": "a"}]}, {"grade": 6, "n": 19, "title": "Добрый Аскар", "author": "Баянгали Алимжанов", "questions": [{"n": 1, "question": "В кого превращается добрый старик Аскар после чудесного события?", "opts": {"a": "В птицу", "b": "В маленького мальчика", "c": "В коня", "d": "Ни в кого, остаётся стариком"}, "correct": "b"}, {"n": 2, "question": "С каким известным героем казахских сказок Аскар знакомится первым в сказочном мире?", "opts": {"a": "С Алдаром Косе", "b": "С Ер-Тостиком", "c": "С Кобланды-батыром", "d": "С Алпамысом"}, "correct": "a"}, {"n": 3, "question": "Каких сказочных персонажей Аскар встречает во второй части сказки?", "opts": {"a": "Тайсогана, Желаяка, Колтаусара, Епти", "b": "Богатырей и ханов", "c": "Космонавтов", "d": "Морских чудовищ"}, "correct": "a"}, {"n": 4, "question": "От кого Аскар спасает детёнышей скота в третьей части сказки?", "opts": {"a": "От Жезтырнак и Жалмауыз-кемпир", "b": "От дракона", "c": "От разбойников", "d": "От наводнения"}, "correct": "a"}, {"n": 5, "question": "Какую главную ценность прославляет эта сказка?", "opts": {"a": "Только силу и оружие", "b": "Доброту и открытое сердце, помогающие обрести друзей", "c": "Стремление к богатству", "d": "Одиночество"}, "correct": "b"}]}, {"grade": 6, "n": 20, "title": "Маленький принц", "author": "Антуан де Сент-Экзюпери", "questions": [{"n": 1, "question": "С какой планеты (астероида) прибыл Маленький принц?", "opts": {"a": "Астероид В-612", "b": "Марс", "c": "Луна", "d": "Земля"}, "correct": "a"}, {"n": 2, "question": "Какой цветок Маленький принц бережно выращивал на своей планете?", "opts": {"a": "Розу", "b": "Подсолнух", "c": "Тюльпан", "d": "Лилию"}, "correct": "a"}, {"n": 3, "question": "Кого встречает рассказчик (пилот) в пустыне Сахара?", "opts": {"a": "Маленького принца", "b": "Только льва", "c": "Только змею", "d": "Только короля"}, "correct": "a"}, {"n": 4, "question": "Какую важную фразу о дружбе говорит Лис Маленькому принцу?", "opts": {"a": "«Приручать» значит «связывать себя узами»", "b": "Ничего важного не говорит", "c": "Учит его только играть", "d": "Говорит только о еде"}, "correct": "a"}, {"n": 5, "question": "В чём заключается главная идея сказки о невидимом?", "opts": {"a": "Самое главное можно увидеть только сердцем", "b": "Важно только то, что видно глазами", "c": "Ничто не имеет значения", "d": "Игрушки — самое важное"}, "correct": "a"}]}, {"grade": 6, "n": 21, "title": "Гарри Поттер и философский камень", "author": "Джоан Роулинг", "questions": [{"n": 1, "question": "В какую школу поступает Гарри Поттер?", "opts": {"a": "Школа магии Хогвартс", "b": "Итонский колледж", "c": "Кембриджский университет", "d": "Оксфордская школа"}, "correct": "a"}, {"n": 2, "question": "Какой особый знак есть на лбу у Гарри?", "opts": {"a": "Звёздочка", "b": "Шрам в виде молнии", "c": "Луна", "d": "Никакого знака нет"}, "correct": "b"}, {"n": 3, "question": "Как зовут двух самых близких друзей Гарри?", "opts": {"a": "Рон Уизли и Гермиона Грейнджер", "b": "Драко и Люциус", "c": "Дадли и Петунья", "d": "Сириус и Люпин"}, "correct": "a"}, {"n": 4, "question": "Как зовут главного злодея в книге?", "opts": {"a": "Дамблдор", "b": "Волан-де-Морт", "c": "Хагрид", "d": "Снейп"}, "correct": "b"}, {"n": 5, "question": "Какими свойствами обладает философский камень в книге?", "opts": {"a": "Даёт возможность летать", "b": "Даёт бессмертие и превращает любой металл в золото", "c": "Позволяет управлять временем", "d": "Никакими свойствами не обладает"}, "correct": "b"}]}, {"grade": 6, "n": 22, "title": "Робинзон Крузо", "author": "Даниель Дефо", "questions": [{"n": 1, "question": "После какого события Робинзон Крузо остаётся один на острове?", "opts": {"a": "После авиакатастрофы", "b": "После крушения корабля во время бури", "c": "После войны", "d": "После похищения"}, "correct": "b"}, {"n": 2, "question": "Что Робинзон обеспечивает себе первым делом, оказавшись на острове?", "opts": {"a": "Поиск друзей", "b": "Еду, укрытие и безопасность", "c": "Накопление богатства", "d": "Постройку корабля"}, "correct": "b"}, {"n": 3, "question": "Как Робинзон называет местного жителя, встреченного спустя годы на острове?", "opts": {"a": "Пятница", "b": "Понедельник", "c": "Воскресенье", "d": "Суббота"}, "correct": "a"}, {"n": 4, "question": "Сколько лет Робинзон провёл на острове, если приблизительно?", "opts": {"a": "Один-два года", "b": "Около двадцати лет", "c": "Сто лет", "d": "Полгода"}, "correct": "b"}, {"n": 5, "question": "Какая главная тема романа?", "opts": {"a": "Жажда богатства", "b": "Стойкость и выживание человека в борьбе с природой", "c": "Жестокость войны", "d": "Любовная драма"}, "correct": "b"}]}, {"grade": 6, "n": 23, "title": "Футбольное поле", "author": "Аделия Амраева", "questions": [{"n": 1, "question": "Каков основной жанр произведения Аделии Амраевой?", "opts": {"a": "Научная фантастика", "b": "Современный рассказ/повесть о детях и подростках", "c": "Историческая хроника", "d": "Пьеса для театра"}, "correct": "b"}, {"n": 2, "question": "Судя по названию, вокруг чего строится сюжет произведения?", "opts": {"a": "Вокруг событий, связанных с футболом и жизнью подростков", "b": "Вокруг космического путешествия", "c": "Вокруг средневековой битвы", "d": "Вокруг подводного мира"}, "correct": "a"}, {"n": 3, "question": "Какую возрастную аудиторию в основном рассматривает автор в своих произведениях?", "opts": {"a": "Только взрослых", "b": "Детей и подростков", "c": "Только пожилых людей", "d": "Только младенцев"}, "correct": "b"}, {"n": 4, "question": "Что чаще всего становится центральной темой в современной казахстанской детской прозе, к которой относится это произведение?", "opts": {"a": "Отношения детей друг с другом, семьёй и окружающим миром", "b": "Только спортивные рекорды", "c": "Только политика", "d": "Только природа без людей"}, "correct": "a"}, {"n": 5, "question": "Для какого возраста читателей рекомендовано данное произведение (согласно школьному списку)?", "opts": {"a": "Только для взрослых", "b": "Для школьников (6 класс)", "c": "Только для дошкольников", "d": "Только для студентов вузов"}, "correct": "b"}]}, {"grade": 6, "n": 24, "title": "Вокруг света за 80 дней", "author": "Жюль Верн", "questions": [{"n": 1, "question": "За сколько дней главный герой Филеас Фогг обязуется обойти вокруг света?", "opts": {"a": "За 30 дней", "b": "За 80 дней", "c": "За 100 дней", "d": "За 365 дней"}, "correct": "b"}, {"n": 2, "question": "Как зовут преданного слугу Филеаса Фогга?", "opts": {"a": "Паспарту", "b": "Ватсон", "c": "Санчо", "d": "Фигаро"}, "correct": "a"}, {"n": 3, "question": "Почему Фогг не может проиграть заключённый спор?", "opts": {"a": "Из-за пари с друзьями по клубу, дело чести", "b": "Из-за участия в гонках", "c": "Из-за подарка королю", "d": "Без особой причины"}, "correct": "a"}, {"n": 4, "question": "Какими видами транспорта пользуются герои во время путешествия?", "opts": {"a": "Только пешком", "b": "Корабль, поезд и даже слон — самые разные виды транспорта", "c": "Только на велосипеде", "d": "Только на лошади"}, "correct": "b"}, {"n": 5, "question": "Основателем какого жанра литературы считается Жюль Верн?", "opts": {"a": "Научной фантастики и приключенческого романа", "b": "Детектива", "c": "Комедии", "d": "Исторического романа"}, "correct": "a"}]}, {"grade": 6, "n": 25, "title": "Путешествие в детство", "author": "Бердибек Сокпакбаев", "questions": [{"n": 1, "question": "В каком жанре в основном написано это произведение автора?", "opts": {"a": "Автобиографическая повесть о собственном детстве писателя", "b": "Научный трактат", "c": "Пьеса", "d": "Стихотворный сборник"}, "correct": "a"}, {"n": 2, "question": "Где происходит действие — в казахском ауле или в другой стране?", "opts": {"a": "В другой стране", "b": "В казахском ауле", "c": "В морском порту", "d": "В большом мегаполисе"}, "correct": "b"}, {"n": 3, "question": "Судя по названию, произведение переносит читателя куда?", "opts": {"a": "В будущее", "b": "В детство героя-рассказчика", "c": "В космос", "d": "В подводный мир"}, "correct": "b"}, {"n": 4, "question": "Какой общий стиль присущ произведениям Сокпакбаева о детстве?", "opts": {"a": "Мрачный и трагический без юмора", "b": "Тёплый, с юмором и жизненными наблюдениями", "c": "Строго научный", "d": "Фантастический"}, "correct": "b"}, {"n": 5, "question": "Чем ценны такие автобиографические повести для читателя-подростка?", "opts": {"a": "Ничем не ценны", "b": "Позволяют увидеть жизнь и быт казахского аула прошлых десятилетий через глаза ребёнка", "c": "Только развлекают без смысла", "d": "Учат только историческим датам"}, "correct": "b"}]}, {"grade": 6, "n": 26, "title": "Третий в пятом ряду", "author": "Анатолий Алексин", "questions": [{"n": 1, "question": "Кто в произведениях Анатолия Алексина чаще всего являются главными героями?", "opts": {"a": "Взрослые чиновники", "b": "Школьники и их взаимоотношения в классе", "c": "Военные", "d": "Иностранные путешественники"}, "correct": "b"}, {"n": 2, "question": "Какая тема характерна для большинства повестей Алексина о школе?", "opts": {"a": "Только приключения на море", "b": "Нравственный выбор, честность и ответственность перед коллективом", "c": "Только спортивные соревнования", "d": "Только природа"}, "correct": "b"}, {"n": 3, "question": "Где происходит действие повести согласно её названию — в каком месте?", "opts": {"a": "На корабле", "b": "В школьном классе (упоминание ряда и места)", "c": "В лесу", "d": "В деревне без школы"}, "correct": "b"}, {"n": 4, "question": "Каким языком в основном пишет Алексин — простым и понятным подростку, или сложным научным?", "opts": {"a": "Сложным научным языком", "b": "Простым, доступным подростку языком", "c": "Стихотворным языком", "d": "Только на латыни"}, "correct": "b"}, {"n": 5, "question": "Чему в основном учат повести Алексина юного читателя?", "opts": {"a": "Ничему не учат", "b": "Размышлять о собственных поступках и об отношениях с окружающими", "c": "Только законам физики", "d": "Только правилам дорожного движения"}, "correct": "b"}]}, {"grade": 6, "n": 27, "title": "Чучело", "author": "Владимир Железников", "questions": [{"n": 1, "question": "Как зовут главную героиню повести, которую одноклассники прозвали Чучелом?", "opts": {"a": "Лена Бессольцева", "b": "Марина Иванова", "c": "Таня Смирнова", "d": "Оля Петрова"}, "correct": "a"}, {"n": 2, "question": "Почему одноклассники начинают травить (бойкотировать) главную героиню?", "opts": {"a": "Она отказалась выдать имя того, кто на самом деле совершил проступок, и класс решил, что виновата она", "b": "Она украла деньги", "c": "Она переехала в другую школу", "d": "Она поссорилась с учителем"}, "correct": "a"}, {"n": 3, "question": "Кем приходится главной героине пожилой человек, известный как чудак-коллекционер картин?", "opts": {"a": "Дедушка", "b": "Дядя", "c": "Сосед, не родственник", "d": "Учитель"}, "correct": "a"}, {"n": 4, "question": "Какая главная нравственная тема поднимается в повести?", "opts": {"a": "Жестокость толпы, травля и цена личного достоинства", "b": "Только школьные оценки", "c": "Только спортивные достижения", "d": "Только семейный отдых"}, "correct": "a"}, {"n": 5, "question": "Произведение «Чучело» также известно благодаря чему, помимо повести?", "opts": {"a": "Только благодаря повести, других версий не существует", "b": "Известной советской экранизации (фильму)", "c": "Мюзиклу на Бродвее", "d": "Компьютерной игре"}, "correct": "b"}]}, {"grade": 6, "n": 28, "title": "Приключения Тома Сойера", "author": "Марк Твен", "questions": [{"n": 1, "question": "Где происходит действие романа — в каком городке на берегу какой реки?", "opts": {"a": "В городке на берегу Миссисипи", "b": "В городе на берегу Нила", "c": "В деревне у моря", "d": "В горном селении"}, "correct": "a"}, {"n": 2, "question": "Чем знаменита сцена с покраской забора в начале романа?", "opts": {"a": "Том красит забор с большим удовольствием сам", "b": "Том хитростью заставляет других мальчишек красить забор за него, выдавая это за привилегию", "c": "Забор красит взрослый", "d": "Забор никто не красит"}, "correct": "b"}, {"n": 3, "question": "С кем Том Сойер дружит и путешествует по приключениям — как зовут его друга?", "opts": {"a": "Гекльберри Финн", "b": "Шерлок Холмс", "c": "Робинзон Крузо", "d": "Оливер Твист"}, "correct": "a"}, {"n": 4, "question": "Какое опасное происшествие с пещерой происходит в романе?", "opts": {"a": "Том и Бекки заблудились в пещере", "b": "Пещеры в романе нет", "c": "Том нашёл пещеру, но не заходил внутрь", "d": "Пещера обвалилась сразу"}, "correct": "a"}, {"n": 5, "question": "Какой клад в итоге находит Том вместе с другом?", "opts": {"a": "Золотые монеты, спрятанные разбойниками", "b": "Древние рукописи", "c": "Оружие", "d": "Ничего не находит"}, "correct": "a"}]}, {"grade": 6, "n": 29, "title": "Остров сокровищ", "author": "Роберт Льюис Стивенсон", "questions": [{"n": 1, "question": "Как зовут главного героя-мальчика, от чьего имени ведётся рассказ?", "opts": {"a": "Джим Хокинс", "b": "Джон Сильвер", "c": "Билли Бонс", "d": "Капитан Смоллетт"}, "correct": "a"}, {"n": 2, "question": "Как зовут одноногого пирата, одного из самых известных персонажей романа?", "opts": {"a": "Долговязый Джон Сильвер", "b": "Капитан Флинт", "c": "Бен Ганн", "d": "Сквайр Трелони"}, "correct": "a"}, {"n": 3, "question": "Что за документ становится ключом к поиску острова сокровищ?", "opts": {"a": "Карта капитана Флинта", "b": "Письмо короля", "c": "Дневник Джима", "d": "Билет на корабль"}, "correct": "a"}, {"n": 4, "question": "На корабле, отправившемся за сокровищами, что в итоге поднимают против капитана некоторые матросы?", "opts": {"a": "Мятеж (бунт пиратов среди экипажа)", "b": "Праздник", "c": "Забастовку из-за еды", "d": "Ничего не поднимают"}, "correct": "a"}, {"n": 5, "question": "Чему в целом посвящён роман?", "opts": {"a": "Приключениям, поиску пиратского клада и предательству", "b": "Только школьной жизни", "c": "Только семейной драме", "d": "Только научным открытиям"}, "correct": "a"}]}, {"grade": 6, "n": 30, "title": "В тылу врага", "author": "Касым Кайсенов", "questions": [{"n": 1, "question": "В основе произведения лежат реальные события какой войны?", "opts": {"a": "Первой мировой войны", "b": "Великой Отечественной войны (Второй мировой)", "c": "Гражданской войны", "d": "Афганской войны"}, "correct": "b"}, {"n": 2, "question": "Кем был сам автор Касым Кайсенов во время описываемых событий?", "opts": {"a": "Мирным жителем, не участвовавшим в войне", "b": "Партизаном, действовавшим в тылу врага", "c": "Врачом в госпитале", "d": "Иностранным журналистом"}, "correct": "b"}, {"n": 3, "question": "В каком жанре в основном написано произведение?", "opts": {"a": "Полностью вымышленный фэнтези-роман", "b": "Автобиографическое военное произведение (мемуары/повесть)", "c": "Комедия", "d": "Детская сказка"}, "correct": "b"}, {"n": 4, "question": "Что означает выражение «в тылу врага» применительно к партизанской борьбе?", "opts": {"a": "Действия на территории, захваченной противником, в его тылу", "b": "Действия только на своей территории", "c": "Действия в море", "d": "Действия в воздухе"}, "correct": "a"}, {"n": 5, "question": "Какую главную ценность прославляет это произведение?", "opts": {"a": "Трусость", "b": "Мужество, стойкость и патриотизм в тяжёлые годы войны", "c": "Богатство", "d": "Развлечения"}, "correct": "b"}]}, {"grade": 7, "n": 1, "title": "Ұшқан ұя", "author": "Бауыржан Момышұлы", "questions": [{"n": 1, "question": "«Ұшқан ұя» шығармасы қандай жанрда жазылған?", "opts": {"a": "Ғылыми фантастика", "b": "Автордың өз балалық шағы туралы мемуарлық (естелік) шығарма", "c": "Детектив романы", "d": "Ертегі"}, "correct": "b"}, {"n": 2, "question": "Шығармада Бауыржанды кім тәрбиелеген — оқиғада ерекше орын алатын кейіпкер кім?", "opts": {"a": "Әжесі Қызтумас", "b": "Патша", "c": "Мұғалімі", "d": "Көршісі"}, "correct": "a"}, {"n": 3, "question": "Бауыржанның әкесі қандай кәсіптермен айналысқан шебер адам болған?", "opts": {"a": "Тек мал шаруашылығымен", "b": "Ағаш ұста, зергер, етікші — көп өнерлі шебер", "c": "Тек саудагер", "d": "Тек әскери адам"}, "correct": "b"}, {"n": 4, "question": "Бауыржан үш жасқа келгенде отбасында қандай қайғылы оқиға болды?", "opts": {"a": "Анасы Рәзия қайтыс болды", "b": "Үйі өртенді", "c": "Ауылдан көшті", "d": "Ешбір оқиға болмады"}, "correct": "a"}, {"n": 5, "question": "Шығарма қазақ халқының қандай тұрмыс-салтын да толық бейнелейді, соған қоса мемуар да болып саналады?", "opts": {"a": "Тек қазіргі заман өмірін", "b": "Дәстүр, ғұрып, ұлттық дүниетанымды (этнографиялық сипатта)", "c": "Тек ғарыш тақырыбын", "d": "Тек шет елдер тұрмысын"}, "correct": "b"}]}, {"grade": 7, "n": 2, "title": "Көксерек", "author": "Мұхтар Әуезов", "questions": [{"n": 1, "question": "«Көксерек» шығармасында бас кейіпкер бала кімді асырап алады?", "opts": {"a": "Түлкі балаcын", "b": "Қасқыр балаcын (бөлтірікті)", "c": "Аюдың балаcын", "d": "Жолбарыс балаcын"}, "correct": "b"}, {"n": 2, "question": "Балалық шағында үй жануары ретінде өскен қасқыр ақыр аяғында қалай аяқталады?", "opts": {"a": "Иесіне мәңгі берілген үй жануары болып қалады", "b": "Табиғи инстинкті басым түсіп, қайтадан жыртқыш аңға айналады", "c": "Ауылдан тыныш кетіп қалады", "d": "Аңшылар оны құтқарып, орманға жібереді"}, "correct": "b"}, {"n": 3, "question": "Шығармада көтерілетін басты идея — не туралы?", "opts": {"a": "Табиғи болмысты (инстинктті) тәрбиемен өзгерту мүмкін емес екені", "b": "Қасқырлар қашанда адалдыққа берілген", "c": "Ауыл балаларының ойын-сауығы", "d": "Аңшылықтың пайдасы"}, "correct": "a"}, {"n": 4, "question": "Автор Мұхтар Әуезов қазақ әдебиетінде негізінен қандай жазушы ретінде танымал?", "opts": {"a": "Тек ақын ретінде", "b": "Ұлы жазушы, драматург, «Абай жолы» эпопеясының авторы", "c": "Тек аудармашы ретінде", "d": "Тек тарихшы ретінде"}, "correct": "b"}, {"n": 5, "question": "«Көксерек» оқиғасы қай ортада — қандай кәсіппен айналысатын адамдар арасында өтеді?", "opts": {"a": "Балықшылар арасында", "b": "Мал шаруашылығымен айналысатын ауыл адамдары арасында", "c": "Кеншілер арасында", "d": "Теңізшілер арасында"}, "correct": "b"}]}, {"grade": 7, "n": 3, "title": "Мейірімді Асқар", "author": "Баянғали Әлімжанов", "questions": [{"n": 1, "question": "Ертегінің басында Асқар қария бір ғажайып оқиғадан соң кімге айналады?", "opts": {"a": "Патшаға", "b": "Кішкентай балаға", "c": "Құсқа", "d": "Батырға"}, "correct": "b"}, {"n": 2, "question": "Асқар ертегі әлемінде саяхаттап жүріп қай әйгілі қазақ ертегі кейіпкерімен алдымен танысады (кемпеске/қулықпен танылған)?", "opts": {"a": "Алдар көсемен", "b": "Ер Төстікпен", "c": "Қобыланды батырмен", "d": "Алпамыс батырмен"}, "correct": "a"}, {"n": 3, "question": "Ертегінің екінші бөлімінде Асқар қандай кейіпкерлермен дос болады?", "opts": {"a": "Батырлар мен хандармен", "b": "Таусоғар, Желаяқ, Көлтаусар, Епті сияқты ертегі кейіпкерлерімен", "c": "Ғарышкерлермен", "d": "Теңіз құбыжықтарымен"}, "correct": "b"}, {"n": 4, "question": "Үшінші бөлімде («Мейірімді Асқар мен момын төлдер») Асқар кімдерден мал төлдерін құтқарады?", "opts": {"a": "Жезтырнақ пен Жалмауыз кемпірден", "b": "Айдаһардан", "c": "Қарақшылардан", "d": "Суда батудан"}, "correct": "a"}, {"n": 5, "question": "Ертегі негізінен қандай құндылықты дәріптейді?", "opts": {"a": "Тек күш пен қаруды", "b": "Мейірімділік пен ақ пейілдің арқасында достық табу", "c": "Байлыққа ұмтылуды", "d": "Жалғыздықты"}, "correct": "b"}]}, {"grade": 7, "n": 4, "title": "Ақ азу", "author": "Джек Лондон", "questions": [{"n": 1, "question": "Ақ азу қандай жануардың ұрпағы — таза қасқыр ма, әлде қасқыр мен иттен туған ба?", "opts": {"a": "Таза қасқыр", "b": "Қасқыр мен иттен туған будан", "c": "Таза ит", "d": "Түлкі"}, "correct": "b"}, {"n": 2, "question": "Ақ азуды алғаш қолға үйретуші үндіс аңшысының есімі кім?", "opts": {"a": "Сұр Қамқа (Grey Beaver)", "b": "Джон Сильвер", "c": "Робинзон", "d": "Гекльберри"}, "correct": "a"}, {"n": 3, "question": "Ақ азуды кейін қандай қатыгез иесі сатып алып, оны итке итпен ұрыстыруға мәжбүрлейді?", "opts": {"a": "Уидон Скотт", "b": "Бьюти Смит", "c": "Капитан Флинт", "d": "Джим Хокинс"}, "correct": "b"}, {"n": 4, "question": "Ақ азуды ақыр соңында кім құтқарып, мейірімге бөлейді?", "opts": {"a": "Уидон Скотт", "b": "Бьюти Смит", "c": "Ешкім құтқармайды", "d": "Аңшылар"}, "correct": "a"}, {"n": 5, "question": "Роман негізінен қандай тақырыпты дәріптейді?", "opts": {"a": "Тек аңшылықтың пайдасын", "b": "Қатыгездік пен мейірімнің жануар мінезіне тигізетін әсерін", "c": "Ғарышты игеруді", "d": "Теңіз саяхатын"}, "correct": "b"}]}, {"grade": 7, "n": 5, "title": "Шұғаның белгісі", "author": "Бейімбет Майлин", "questions": [{"n": 1, "question": "Шұға кімнің қызы?", "opts": {"a": "Жаппас Есімбек байдың", "b": "Хандың", "c": "Мұғалімнің", "d": "Саудагердің"}, "correct": "a"}, {"n": 2, "question": "Шұға ауыл сыртындағы алтыбақанда алдымен кіммен танысып, ғашық болады?", "opts": {"a": "Әбдірахманмен", "b": "Қасыммен", "c": "Патшамен", "d": "Аңшымен"}, "correct": "a"}, {"n": 3, "question": "Шұға мен Әбдірахман кездесулері сиреп кеткенде бір-бірімен қалай хабарласады?", "opts": {"a": "Тек хат арқылы", "b": "Тек телефон арқылы", "c": "Ешқашан хабарласпайды", "d": "Үшінші адам арқылы ғана"}, "correct": "a"}, {"n": 4, "question": "Шығарма қандай аяқталады — қуанышты ма, әлде қайғылы ма?", "opts": {"a": "Қуанышты, үйлену тойымен", "b": "Қайғылы, Шұғаның қазасымен және оның басына белгі қойылуымен", "c": "Ешбір аяқталуы жоқ, ашық қалады", "d": "Комедиялық түрде аяқталады"}, "correct": "b"}, {"n": 5, "question": "Повесть негізінен қандай әлеуметтік тақырыпты көтереді?", "opts": {"a": "Ғылыми жаңалықтарды", "b": "Салт-дәстүрдің қыз тағдырына салған шектеуі мен махаббат еркіндігінің тартысын", "c": "Спорттық жарыстарды", "d": "Саяхат тәжірибесін"}, "correct": "b"}]}, {"grade": 7, "n": 6, "title": "Ауылдан шыққан миллионер", "author": "Сәуле Досжанова", "questions": [{"n": 1, "question": "Шығарманың бас кейіпкері — қандай есімді бала?", "opts": {"a": "Жомарт", "b": "Асан", "c": "Ерлан", "d": "Бекзат"}, "correct": "a"}, {"n": 2, "question": "Кітап негізінен қандай сипатта жазылған — тек ойын-сауық үшін бе, әлде мотивациялық мақсатпен бе?", "opts": {"a": "Тек ойын-сауық үшін", "b": "Балаларды еңбекке, ісін жасауға баулитын мотивациялық шығарма", "c": "Тек тарихи деректеме", "d": "Тек ғылыми-көпшілік мақала"}, "correct": "b"}, {"n": 3, "question": "Жомарттың табыс жолы қандай құндылыққа негізделеді?", "opts": {"a": "Тек сәттілік пен кезекке", "b": "Еңбекқорлық пен нарық талабын жастайынан білуге", "c": "Алаяқтыққа", "d": "Мұрагерлік байлыққа"}, "correct": "b"}, {"n": 4, "question": "Автор Сәуле Досжанова бұл шығарманы негізінен кімге арнап жазған?", "opts": {"a": "Тек ересектерге", "b": "Ауыл балалары мен жасөспірімдерге", "c": "Тек шетелдіктерге", "d": "Тек ғалымдарға"}, "correct": "b"}, {"n": 5, "question": "Жомарт есейе келе кімге қамқорлық жасайды, бұл ұлттық тәрбиенің көрінісі ретінде аталады?", "opts": {"a": "Анасына", "b": "Мұғаліміне", "c": "Көршісіне", "d": "Ешкімге"}, "correct": "a"}]}, {"grade": 7, "n": 7, "title": "Ай мен Айша", "author": "Шерхан Мұртаза", "questions": [{"n": 1, "question": "Роман авторының өз анасы кім деп аталады, шығарма соның есімімен аталған?", "opts": {"a": "Айша", "b": "Ләззат", "c": "Гүлнар", "d": "Батима"}, "correct": "a"}, {"n": 2, "question": "Шығармада баяндаушы бала кейіпкер қалай аталады?", "opts": {"a": "Барсхан", "b": "Қожа", "c": "Асан", "d": "Ерлан"}, "correct": "a"}, {"n": 3, "question": "Роман қандай тарихи қиын кезеңдердегі ауыл өмірін баяндайды?", "opts": {"a": "Тәуелсіздік алғаннан кейінгі жылдар", "b": "Ашаршылық пен репрессия жылдары", "c": "Қазіргі заман", "d": "Хандық дәуір"}, "correct": "b"}, {"n": 4, "question": "Барсхан мектепте қандай әділетсіздікке тап болады?", "opts": {"a": "Мұғалім оны «халық жауының» баласы деп қабылдағысы келмейді", "b": "Ешбір қиындық болмайды", "c": "Ол мектепке мүлде бармайды", "d": "Ол бірінші оқушы атанады"}, "correct": "a"}, {"n": 5, "question": "Шығарма қандай тақырыпқа арналған қазақ әдебиетіндегі шоқтығы биік туындылардың бірі саналады?", "opts": {"a": "Ғарышты игеру тақырыбына", "b": "Ана тақырыбына (ана мейірімі мен қайсарлығына)", "c": "Спорт тақырыбына", "d": "Ғылым тақырыбына"}, "correct": "b"}]}, {"grade": 7, "n": 8, "title": "Том Сойердің басынан кешкендері", "author": "Марк Твен", "questions": [{"n": 1, "question": "Оқиға қай өзен жағасындағы қалашықта өтеді?", "opts": {"a": "Миссисипи өзені жағасында", "b": "Ніл өзені жағасында", "c": "Еділ өзені жағасында", "d": "Теңіз жағасында"}, "correct": "a"}, {"n": 2, "question": "Том Сойер қоршауды бояу ісін қалай шешеді — өзі бояп бітіре ме, әлде басқаларды қалай көндіреді?", "opts": {"a": "Өзі жалғыз бояп бітіреді", "b": "Айла жасап, басқа балаларды бояуды артықшылық деп сеніп, өзіне бояттырады", "c": "Қоршауды мүлде боямайды", "d": "Әкесіне бояттырады"}, "correct": "b"}, {"n": 3, "question": "Томның ең жақын досының есімі кім?", "opts": {"a": "Гекльберри Финн", "b": "Шерлок Холмс", "c": "Робинзон Крузо", "d": "Оливер Твист"}, "correct": "a"}, {"n": 4, "question": "Роман барысында Том мен Бекки қандай қауіпті жағдайға тап болады?", "opts": {"a": "Үңгірде адасып қалады", "b": "Кемеде суға кетеді", "c": "Тауда қар көшкінінде қалады", "d": "Ешбір қауіпті жағдай болмайды"}, "correct": "a"}, {"n": 5, "question": "Том мен досы ақыр соңында қандай қазына табады?", "opts": {"a": "Қарақшылар жасырған алтын тиындарды", "b": "Ежелгі қолжазбаларды", "c": "Қару-жарақты", "d": "Ешнәрсе таппайды"}, "correct": "a"}]}, {"grade": 7, "n": 9, "title": "Ауыл шетіндегі үй", "author": "Әкім Тарази", "questions": [{"n": 1, "question": "Бұл кітап негізінен қандай түрде жарық көрген — жалғыз үлкен роман ба, әлде әңгімелер жинағы ма?", "opts": {"a": "Жалғыз үлкен роман", "b": "Түрлі жылдары жазылған әңгімелер топтамасы", "c": "Өлеңдер жинағы", "d": "Ғылыми мақалалар жинағы"}, "correct": "b"}, {"n": 2, "question": "Автор Әкім Тарази қазақ әдебиетінде негізінен кім ретінде танымал?", "opts": {"a": "Белгілі жазушы, драматург, «Еңбек Ері» атанған қаламгер", "b": "Тек аудармашы", "c": "Тек журналист", "d": "Тек тарихшы"}, "correct": "a"}, {"n": 3, "question": "Жинақтың алғашқы әңгімесі «Жалын» журналының тұңғыш нөмірінде қандай атпен жарық көрген?", "opts": {"a": "«Ауыл шетіндегі үй»", "b": "«Әнім сен едіңнен»", "c": "«Соңғы сапар»", "d": "«Дала үні»"}, "correct": "b"}, {"n": 4, "question": "Шығармалар негізінен қандай ортадағы адамдардың тағдырын суреттейді?", "opts": {"a": "Қала тұрғындарының", "b": "Қазақ ауылының адамдары мен сол кездегі қоғам қайшылығын", "c": "Теңізшілердің", "d": "Ғарышкерлердің"}, "correct": "b"}, {"n": 5, "question": "Мұндай әңгімелер топтамасы оқырманға негізінен нені көрсетуге тырысады?", "opts": {"a": "Тек күлкілі жағдайларды", "b": "Уақыт таңбасы мен замана шындығын, адамдардың мінез-тағдырын", "c": "Тек ертегі әлемін", "d": "Тек ғылыми фактілерді"}, "correct": "b"}]}, {"grade": 7, "n": 10, "title": "Әлемді 80 күн ішінде шарлау", "author": "Жюль Верн", "questions": [{"n": 1, "question": "Бас кейіпкер Филеас Фогг әлемді неше күнде аралап шығуға бәстеседі?", "opts": {"a": "30 күнде", "b": "80 күнде", "c": "100 күнде", "d": "365 күнде"}, "correct": "b"}, {"n": 2, "question": "Фоггтың адал қызметшісінің есімі кім?", "opts": {"a": "Паспарту", "b": "Ватсон", "c": "Санчо", "d": "Фигаро"}, "correct": "a"}, {"n": 3, "question": "Фогг бәсті неге ұтылмауы керек еді?", "opts": {"a": "Достарымен клубта бәстескені үшін, намыс үшін", "b": "Жарысқа қатысу үшін", "c": "Патшаға сый үшін", "d": "Ешбір себепсіз"}, "correct": "a"}, {"n": 4, "question": "Саяхат барысында олар негізінен қандай көлік түрлерін қолданады?", "opts": {"a": "Тек жаяу жүру", "b": "Кеме, теміржол, пойыз, тіпті піл сияқты әртүрлі көлік", "c": "Тек ат", "d": "Тек велосипед"}, "correct": "b"}, {"n": 5, "question": "Роман авторы Жюль Верн негізінен қандай жанрдың атасы саналады?", "opts": {"a": "Ғылыми фантастика мен саяхат романдарының", "b": "Детектив жанрының", "c": "Комедия жанрының", "d": "Тарихи роман жанрының"}, "correct": "a"}]}, {"grade": 7, "n": 11, "title": "Хәрри Поттер және пәлсапа тасы", "author": "Джоан Роулинг", "questions": [{"n": 1, "question": "Гарри Поттер қай мектепте оқуға түседі?", "opts": {"a": "Хогвартс сиқыршылар мектебі", "b": "Итон колледжі", "c": "Кембридж университеті", "d": "Оксфорд мектебі"}, "correct": "a"}, {"n": 2, "question": "Гарридің ерекшелігі — маңдайында қандай белгі бар?", "opts": {"a": "Жұлдыз тәрізді белгі", "b": "Найзағай тәрізді тыртық", "c": "Айдай белгі", "d": "Ешбір белгі жоқ"}, "correct": "b"}, {"n": 3, "question": "Гарридің ең жақын екі досының есімдері кім?", "opts": {"a": "Рон Уизли мен Гермиона Грейнджер", "b": "Драко мен Люциус", "c": "Дадли мен Петуния", "d": "Сириус пен Люпин"}, "correct": "a"}, {"n": 4, "question": "Кітаптағы басты жауыз кейіпкердің есімі кім?", "opts": {"a": "Дамблдор", "b": "Волдеморт", "c": "Хагрид", "d": "Снейп"}, "correct": "b"}, {"n": 5, "question": "«Пәлсапа тасы» кітапта қандай қасиетімен ерекшеленеді?", "opts": {"a": "Ұшуға мүмкіндік береді", "b": "Мәңгілік өмір сүруге және кез келген затты алтынға айналдыруға көмектеседі", "c": "Уақытты бақылауға мүмкіндік береді", "d": "Ешбір қасиеті жоқ"}, "correct": "b"}]}, {"grade": 7, "n": 12, "title": "Жасампаз жасөспірімнің 7 дағдысы", "author": "Шон Кови", "questions": [{"n": 1, "question": "Кітап негізінен қандай жанрда жазылған?", "opts": {"a": "Көркем әңгіме", "b": "Жасөспірімдерге арналған өзін-өзі дамыту (мотивациялық) кітап", "c": "Ғылыми-фантастика романы", "d": "Тарихи хроника"}, "correct": "b"}, {"n": 2, "question": "Кітап авторы Шон Кови кімнің «7 дағды» идеясын жасөспірімдерге бейімдеп жазған?", "opts": {"a": "Өз әкесі Стивен Ковидің идеясын", "b": "Ешкімнің идеясын пайдаланбаған, толығымен жаңа", "c": "Дейл Карнегидің идеясын", "d": "Наполеон Хиллдің идеясын"}, "correct": "a"}, {"n": 3, "question": "Кітапта «Проактивті бол» дағдысы негізінен нені білдіреді?", "opts": {"a": "Тек күту, ешнәрсе істемеу", "b": "Жағдайларға жауап беруде өз таңдауыңды өзің жасау, бастамашыл болу", "c": "Басқалардың айтқанын ғана орындау", "d": "Ешкіммен санаспау"}, "correct": "b"}, {"n": 4, "question": "Кітап оқырманға негізінен қандай мақсатпен жазылған?", "opts": {"a": "Тек ойын-сауық үшін", "b": "Жасөспірімдерге өмірде табысты болуға көмектесетін тиімді әдеттерді үйрету", "c": "Тек тарихты үйрету", "d": "Тек тілдерді үйрету"}, "correct": "b"}, {"n": 5, "question": "«7 дағды» тұжырымдамасында дағдылардың неше тобы бар (жеке жеңіс, қоғамдық жеңіс)?", "opts": {"a": "Тек біреу", "b": "Екі негізгі топ (жеке және қоғамдық жеңістер)", "c": "Он топ", "d": "Топтарға бөлінбейді"}, "correct": "b"}]}, {"grade": 7, "n": 13, "title": "Кішкентай ханзада", "author": "Антуан де Сент-Экзюпери", "questions": [{"n": 1, "question": "Кішкентай ханзада қай планетадан келген?", "opts": {"a": "В-612 астероидынан", "b": "Марстан", "c": "Айдан", "d": "Жерден"}, "correct": "a"}, {"n": 2, "question": "Кішкентай ханзада өз планетасында қандай гүлді жақсы көреді және оны күтеді?", "opts": {"a": "Раушан гүлін", "b": "Күнбағысты", "c": "Тюльпанды", "d": "Лалагүлді"}, "correct": "a"}, {"n": 3, "question": "Хикаяны баяндайтын кейіпкер (пилот) кіммен Сахара шөлінде кездеседі?", "opts": {"a": "Кішкентай ханзадамен", "b": "Патшамен", "c": "Түлкімен ғана", "d": "Жыланмен ғана"}, "correct": "a"}, {"n": 4, "question": "Хикаяда түлкі Кішкентай ханзадаға достық туралы қандай маңызды сөз айтады («үйрету»)?", "opts": {"a": "«Достасу» деген «уайымдау»", "b": "«Үйрету» деген «баулу»", "c": "Ешнәрсе айтпайды", "d": "Тек ойнауды үйретеді"}, "correct": "b"}, {"n": 5, "question": "Хикаяның негізгі идеясы — көзге көрінбейтін нәрсенің маңызы туралы. Бұл қандай ой?", "opts": {"a": "Ең маңызды нәрселерді жүрекпен ғана көруге болады", "b": "Тек көзге көрінетін нәрсе бағалы", "c": "Ешнәрсенің мәні жоқ", "d": "Ойыншықтар ең маңызды"}, "correct": "a"}]}, {"grade": 7, "n": 14, "title": "Робинзон Крузо", "author": "Даниель Дефо", "questions": [{"n": 1, "question": "Робинзон Крузо қандай оқиғадан кейін аралда жалғыз қалады?", "opts": {"a": "Ұшақ апатынан кейін", "b": "Кеме апатынан (борандан) кейін", "c": "Соғыстан кейін", "d": "Ұрланғаннан кейін"}, "correct": "b"}, {"n": 2, "question": "Робинзон аралда жалғыз болғанда алдымен нені қамтамасыз етуге тырысады?", "opts": {"a": "Достар табу", "b": "Тамақ, баспана және қауіпсіздік", "c": "Байлық жинау", "d": "Кеме жасау"}, "correct": "b"}, {"n": 3, "question": "Робинзон аралда ұзақ жылдар бойы кездестірген жергілікті тұрғынды қалай атайды?", "opts": {"a": "Пятница (Жұма)", "b": "Понедельник", "c": "Воскресенье", "d": "Сенбі"}, "correct": "a"}, {"n": 4, "question": "Робинзон аралда қанша жылдай өмір сүреді (шамамен)?", "opts": {"a": "Бір-екі жыл", "b": "Жиырма шақты жыл", "c": "Жүз жыл", "d": "Алты ай"}, "correct": "b"}, {"n": 5, "question": "Роман негізінен қандай тақырыпты дәріптейді?", "opts": {"a": "Байлыққа құмарлықты", "b": "Адамның төзімділігі мен табиғатпен күресте аман қалуын", "c": "Соғыс қаталдығын", "d": "Ғашықтық драмасын"}, "correct": "b"}]}, {"grade": 7, "n": 15, "title": "Мұзтау", "author": "Оралхан Бокей", "questions": [{"n": 1, "question": "Повестің бас кейіпкері кім деп аталады?", "opts": {"a": "Ақтан", "b": "Серік", "c": "Дәурен", "d": "Болат"}, "correct": "a"}, {"n": 2, "question": "Ақтан балалық шағынан бері негізінен қандай малмен (аңмен) тығыз байланыста өседі?", "opts": {"a": "Жылқымен", "b": "Бұғылармен", "c": "Түйемен", "d": "Қойлармен"}, "correct": "b"}, {"n": 3, "question": "Ақтанның әкесі не болған, ол неге жалғыз қалды?", "opts": {"a": "Соғыстан оралмаған", "b": "Қалаға көшіп кетті", "c": "Ешқашан болмаған", "d": "Аңшылықта қаза тапты (басқа себеп)"}, "correct": "a"}, {"n": 4, "question": "Ауылды тастап кетпей, Ақтан қандай қызмет атқаруға кіріседі?", "opts": {"a": "Мұғалім болады", "b": "Ауыл күзетшісі болады", "c": "Дәрігер болады", "d": "Милиция болады"}, "correct": "b"}, {"n": 5, "question": "Повестегі қосымша желіде біреу үңгірде жасырылған нені іздейді?", "opts": {"a": "Жасырын қазынаны", "b": "Жоғалған малды", "c": "Ежелгі қолжазбаны", "d": "Су көзін"}, "correct": "a"}]}, {"grade": 7, "n": 16, "title": "Путешествие в детство", "author": "Бердибек Сокпакбаев", "questions": [{"n": 1, "question": "В каком жанре в основном написано это произведение автора?", "opts": {"a": "Автобиографическая повесть о собственном детстве писателя", "b": "Научный трактат", "c": "Пьеса", "d": "Стихотворный сборник"}, "correct": "a"}, {"n": 2, "question": "Где происходит действие — в казахском ауле или в другой стране?", "opts": {"a": "В другой стране", "b": "В казахском ауле", "c": "В морском порту", "d": "В большом мегаполисе"}, "correct": "b"}, {"n": 3, "question": "Судя по названию, произведение переносит читателя куда?", "opts": {"a": "В будущее", "b": "В детство героя-рассказчика", "c": "В космос", "d": "В подводный мир"}, "correct": "b"}, {"n": 4, "question": "Какой общий стиль присущ произведениям Сокпакбаева о детстве?", "opts": {"a": "Мрачный и трагический без юмора", "b": "Тёплый, с юмором и жизненными наблюдениями", "c": "Строго научный", "d": "Фантастический"}, "correct": "b"}, {"n": 5, "question": "Чем ценны такие автобиографические повести для читателя-подростка?", "opts": {"a": "Ничем не ценны", "b": "Позволяют увидеть жизнь и быт казахского аула прошлых десятилетий через глаза ребёнка", "c": "Только развлекают без смысла", "d": "Учат только историческим датам"}, "correct": "b"}]}, {"grade": 7, "n": 17, "title": "Серый Лютый", "author": "Мухтар Ауэзов", "questions": [{"n": 1, "question": "Кого приручает главный герой-мальчик в этой повести?", "opts": {"a": "Лисёнка", "b": "Волчонка", "c": "Медвежонка", "d": "Тигрёнка"}, "correct": "b"}, {"n": 2, "question": "Чем в итоге заканчивается попытка приручить дикого зверя?", "opts": {"a": "Зверь навсегда остаётся преданным домашним питомцем", "b": "В звере побеждает дикая природа, и он возвращается к хищничеству", "c": "Зверь погибает от болезни", "d": "Хозяин отпускает его в зоопарк"}, "correct": "b"}, {"n": 3, "question": "Какая главная идея заложена в повести?", "opts": {"a": "Дикую природу воспитанием изменить невозможно", "b": "Волки всегда преданы человеку", "c": "Охота — это весело", "d": "Аул живёт без животных"}, "correct": "a"}, {"n": 4, "question": "Чем знаменит автор Мухтар Ауэзов в казахской литературе?", "opts": {"a": "Только как переводчик", "b": "Как великий писатель, автор эпопеи «Путь Абая»", "c": "Только как поэт", "d": "Только как историк"}, "correct": "b"}, {"n": 5, "question": "В какой среде происходит действие повести?", "opts": {"a": "Среди рыбаков", "b": "Среди аульных жителей, занимающихся животноводством", "c": "Среди моряков", "d": "Среди горожан"}, "correct": "b"}]}, {"grade": 7, "n": 18, "title": "Робинзон Крузо", "author": "Даниель Дефо", "questions": [{"n": 1, "question": "После какого события Робинзон Крузо остаётся один на острове?", "opts": {"a": "После авиакатастрофы", "b": "После крушения корабля во время бури", "c": "После войны", "d": "После похищения"}, "correct": "b"}, {"n": 2, "question": "Что Робинзон обеспечивает себе первым делом, оказавшись на острове?", "opts": {"a": "Поиск друзей", "b": "Еду, укрытие и безопасность", "c": "Накопление богатства", "d": "Постройку корабля"}, "correct": "b"}, {"n": 3, "question": "Как Робинзон называет местного жителя, встреченного спустя годы на острове?", "opts": {"a": "Пятница", "b": "Понедельник", "c": "Воскресенье", "d": "Суббота"}, "correct": "a"}, {"n": 4, "question": "Сколько лет Робинзон провёл на острове, если приблизительно?", "opts": {"a": "Один-два года", "b": "Около двадцати лет", "c": "Сто лет", "d": "Полгода"}, "correct": "b"}, {"n": 5, "question": "Какая главная тема романа?", "opts": {"a": "Жажда богатства", "b": "Стойкость и выживание человека в борьбе с природой", "c": "Жестокость войны", "d": "Любовная драма"}, "correct": "b"}]}, {"grade": 7, "n": 19, "title": "Маленький принц", "author": "Антуан де Сент-Экзюпери", "questions": [{"n": 1, "question": "С какой планеты (астероида) прибыл Маленький принц?", "opts": {"a": "Астероид В-612", "b": "Марс", "c": "Луна", "d": "Земля"}, "correct": "a"}, {"n": 2, "question": "Какой цветок Маленький принц бережно выращивал на своей планете?", "opts": {"a": "Розу", "b": "Подсолнух", "c": "Тюльпан", "d": "Лилию"}, "correct": "a"}, {"n": 3, "question": "Кого встречает рассказчик (пилот) в пустыне Сахара?", "opts": {"a": "Маленького принца", "b": "Только льва", "c": "Только змею", "d": "Только короля"}, "correct": "a"}, {"n": 4, "question": "Какую важную фразу о дружбе говорит Лис Маленькому принцу?", "opts": {"a": "«Приручать» значит «связывать себя узами»", "b": "Ничего важного не говорит", "c": "Учит его только играть", "d": "Говорит только о еде"}, "correct": "a"}, {"n": 5, "question": "В чём заключается главная идея сказки о невидимом?", "opts": {"a": "Самое главное можно увидеть только сердцем", "b": "Важно только то, что видно глазами", "c": "Ничто не имеет значения", "d": "Игрушки — самое важное"}, "correct": "a"}]}, {"grade": 7, "n": 20, "title": "Гарри Поттер и философский камень", "author": "Джоан Роулинг", "questions": [{"n": 1, "question": "В какую школу поступает Гарри Поттер?", "opts": {"a": "Школа магии Хогвартс", "b": "Итонский колледж", "c": "Кембриджский университет", "d": "Оксфордская школа"}, "correct": "a"}, {"n": 2, "question": "Какой особый знак есть на лбу у Гарри?", "opts": {"a": "Звёздочка", "b": "Шрам в виде молнии", "c": "Луна", "d": "Никакого знака нет"}, "correct": "b"}, {"n": 3, "question": "Как зовут двух самых близких друзей Гарри?", "opts": {"a": "Рон Уизли и Гермиона Грейнджер", "b": "Драко и Люциус", "c": "Дадли и Петунья", "d": "Сириус и Люпин"}, "correct": "a"}, {"n": 4, "question": "Как зовут главного злодея в книге?", "opts": {"a": "Дамблдор", "b": "Волан-де-Морт", "c": "Хагрид", "d": "Снейп"}, "correct": "b"}, {"n": 5, "question": "Какими свойствами обладает философский камень в книге?", "opts": {"a": "Даёт возможность летать", "b": "Даёт бессмертие и превращает любой металл в золото", "c": "Позволяет управлять временем", "d": "Никакими свойствами не обладает"}, "correct": "b"}]}, {"grade": 7, "n": 21, "title": "Футбольное поле", "author": "Аделия Амраева", "questions": [{"n": 1, "question": "Каков основной жанр произведения Аделии Амраевой?", "opts": {"a": "Научная фантастика", "b": "Современный рассказ/повесть о детях и подростках", "c": "Историческая хроника", "d": "Пьеса для театра"}, "correct": "b"}, {"n": 2, "question": "Судя по названию, вокруг чего строится сюжет произведения?", "opts": {"a": "Вокруг событий, связанных с футболом и жизнью подростков", "b": "Вокруг космического путешествия", "c": "Вокруг средневековой битвы", "d": "Вокруг подводного мира"}, "correct": "a"}, {"n": 3, "question": "Какую возрастную аудиторию в основном рассматривает автор в своих произведениях?", "opts": {"a": "Только взрослых", "b": "Детей и подростков", "c": "Только пожилых людей", "d": "Только младенцев"}, "correct": "b"}, {"n": 4, "question": "Что чаще всего становится центральной темой в современной казахстанской детской прозе, к которой относится это произведение?", "opts": {"a": "Отношения детей друг с другом, семьёй и окружающим миром", "b": "Только спортивные рекорды", "c": "Только политика", "d": "Только природа без людей"}, "correct": "a"}, {"n": 5, "question": "Для какого возраста читателей рекомендовано данное произведение (согласно школьному списку)?", "opts": {"a": "Только для взрослых", "b": "Для школьников", "c": "Только для дошкольников", "d": "Только для студентов вузов"}, "correct": "b"}]}, {"grade": 7, "n": 22, "title": "Горький запах полыни", "author": "Саин Муратбеков", "questions": [{"n": 1, "question": "В каком году и в каком возрасте появляется в ауле главный герой Аян?", "opts": {"a": "Весной 1942 года, примерно 10-12 лет", "b": "В 2000 году, взрослым мужчиной", "c": "Летом 1941 года, младенцем", "d": "Никогда не появляется в ауле"}, "correct": "a"}, {"n": 2, "question": "Какая особенность есть у Аяна — почему он не может, как все, бегать и играть?", "opts": {"a": "Он хромой (травма ноги)", "b": "Он слепой", "c": "Он глухой", "d": "У него нет особенностей"}, "correct": "a"}, {"n": 3, "question": "Чем Аян помогает местным детям справляться с тяготами военного времени?", "opts": {"a": "Даёт им еду", "b": "Рассказывает сказки", "c": "Учит их драться", "d": "Ничем не помогает"}, "correct": "b"}, {"n": 4, "question": "Что происходит с Аяном после того, как он узнаёт о гибели отца на фронте?", "opts": {"a": "Он остаётся в ауле навсегда", "b": "Уезжает в детский дом", "c": "Убегает на фронт", "d": "Ничего не меняется"}, "correct": "b"}, {"n": 5, "question": "Что символизирует горький запах полыни в повести?", "opts": {"a": "Запах, исходящий от одежды отцов и братьев, ушедших на фронт — символ разлуки и войны", "b": "Запах степных цветов, не связанный с войной", "c": "Запах готовки в ауле", "d": "Ничего не символизирует"}, "correct": "a"}]}, {"grade": 7, "n": 23, "title": "Приключения Тома Сойера", "author": "Марк Твен", "questions": [{"n": 1, "question": "Где происходит действие романа — в каком городке на берегу какой реки?", "opts": {"a": "В городке на берегу Миссисипи", "b": "В городе на берегу Нила", "c": "В деревне у моря", "d": "В горном селении"}, "correct": "a"}, {"n": 2, "question": "Чем знаменита сцена с покраской забора в начале романа?", "opts": {"a": "Том красит забор с большим удовольствием сам", "b": "Том хитростью заставляет других мальчишек красить забор за него, выдавая это за привилегию", "c": "Забор красит взрослый", "d": "Забор никто не красит"}, "correct": "b"}, {"n": 3, "question": "С кем Том Сойер дружит и путешествует по приключениям — как зовут его друга?", "opts": {"a": "Гекльберри Финн", "b": "Шерлок Холмс", "c": "Робинзон Крузо", "d": "Оливер Твист"}, "correct": "a"}, {"n": 4, "question": "Какое опасное происшествие с пещерой происходит в романе?", "opts": {"a": "Том и Бекки заблудились в пещере", "b": "Пещеры в романе нет", "c": "Том нашёл пещеру, но не заходил внутрь", "d": "Пещера обвалилась сразу"}, "correct": "a"}, {"n": 5, "question": "Какой клад в итоге находит Том вместе с другом?", "opts": {"a": "Золотые монеты, спрятанные разбойниками", "b": "Древние рукописи", "c": "Оружие", "d": "Ничего не находит"}, "correct": "a"}]}, {"grade": 7, "n": 24, "title": "7 навыков высокоэффективных тинейджеров", "author": "Шон Кови", "questions": [{"n": 1, "question": "В каком жанре в основном написана эта книга?", "opts": {"a": "Художественный рассказ", "b": "Мотивационная книга по саморазвитию для подростков", "c": "Научная фантастика", "d": "Историческая хроника"}, "correct": "b"}, {"n": 2, "question": "Чью концепцию «7 навыков» автор Шон Кови адаптировал специально для подростков?", "opts": {"a": "Концепцию своего отца Стивена Кови", "b": "Полностью новую, никем не использованную концепцию", "c": "Концепцию Дейла Карнеги", "d": "Концепцию Наполеона Хилла"}, "correct": "a"}, {"n": 3, "question": "Что означает навык «Будь проактивным» в книге?", "opts": {"a": "Просто ждать и ничего не делать", "b": "Самостоятельно делать выбор в ответ на обстоятельства, проявлять инициативу", "c": "Слушать только других", "d": "Ни с кем не считаться"}, "correct": "b"}, {"n": 4, "question": "С какой целью написана эта книга для подросткового читателя?", "opts": {"a": "Только для развлечения", "b": "Помочь подросткам сформировать эффективные привычки для успеха в жизни", "c": "Только для изучения истории", "d": "Только для изучения языков"}, "correct": "b"}, {"n": 5, "question": "На сколько основных групп делятся навыки в концепции (личная победа, общественная победа)?", "opts": {"a": "Только на одну", "b": "На две основные группы", "c": "На десять групп", "d": "Навыки не делятся на группы"}, "correct": "b"}]}, {"grade": 7, "n": 25, "title": "Ночной выстрел", "author": "Кемель Токаев", "questions": [{"n": 1, "question": "В каком жанре в основном писал автор Кемель Токаев большинство своих произведений?", "opts": {"a": "Любовная лирика", "b": "Детективно-приключенческая проза", "c": "Комедия", "d": "Сказки для малышей"}, "correct": "b"}, {"n": 2, "question": "Каким автор считается в истории казахской литературы?", "opts": {"a": "Основоположником детективного жанра в казахской литературе", "b": "Основателем научной фантастики", "c": "Первым казахским поэтом", "d": "Автором только детских сказок"}, "correct": "a"}, {"n": 3, "question": "О чём в основном рассказывают повести Токаева, включая «Ночной выстрел»?", "opts": {"a": "О подвигах партизан в тылу врага и работе органов правопорядка в раскрытии преступлений", "b": "Только о любовных драмах", "c": "Только о путешествиях по миру", "d": "Только о жизни животных"}, "correct": "a"}, {"n": 4, "question": "Каким был жизненный опыт самого автора, повлиявший на его творчество?", "opts": {"a": "Он был военным сержантом на фронте, был несколько раз ранен", "b": "Он никогда не покидал город", "c": "Он был только учителем", "d": "Он был врачом"}, "correct": "a"}, {"n": 5, "question": "К какому более широкому жанровому направлению относится большинство произведений Токаева?", "opts": {"a": "Детектив и приключения", "b": "Пастораль", "c": "Мемуары о путешествиях", "d": "Юмористические рассказы"}, "correct": "a"}]}, {"grade": 7, "n": 26, "title": "Белый Клык", "author": "Джек Лондон", "questions": [{"n": 1, "question": "Белый Клык является потомком — чистым волком или помесью волка и собаки?", "opts": {"a": "Чистым волком", "b": "Помесью волка и собаки", "c": "Чистой собакой", "d": "Лисой"}, "correct": "b"}, {"n": 2, "question": "Как зовут индейского охотника, который первым приручает Белого Клыка?", "opts": {"a": "Серый Бобёр (Grey Beaver)", "b": "Джон Сильвер", "c": "Робинзон", "d": "Гекльберри"}, "correct": "a"}, {"n": 3, "question": "Какой жестокий хозяин позже покупает Белого Клыка и заставляет его драться с собаками?", "opts": {"a": "Уидон Скотт", "b": "Красавчик Смит", "c": "Капитан Флинт", "d": "Джим Хокинс"}, "correct": "b"}, {"n": 4, "question": "Кто в итоге спасает Белого Клыка и приручает его добротой?", "opts": {"a": "Уидон Скотт", "b": "Красавчик Смит", "c": "Никто не спасает", "d": "Охотники"}, "correct": "a"}, {"n": 5, "question": "Какую главную тему раскрывает роман?", "opts": {"a": "Только польза охоты", "b": "Влияние жестокости и доброты на характер животного", "c": "Освоение космоса", "d": "Морское путешествие"}, "correct": "b"}]}, {"grade": 7, "n": 27, "title": "Мой брат играет на кларнете", "author": "Анатолий Алексин", "questions": [{"n": 1, "question": "От чьего имени ведётся повествование в повести?", "opts": {"a": "От имени семиклассницы Жени", "b": "От имени брата Лёвы", "c": "От имени учителя", "d": "От имени дедушки"}, "correct": "a"}, {"n": 2, "question": "В какой форме написана повесть?", "opts": {"a": "В форме дневника героини", "b": "В форме пьесы", "c": "В форме письма", "d": "В форме стихотворения"}, "correct": "a"}, {"n": 3, "question": "На каком инструменте играет брат Женя — Лёва, и почему именно на нём?", "opts": {"a": "На кларнете, так хотел покойный дедушка", "b": "На скрипке, по своему выбору", "c": "На фортепиано, по требованию школы", "d": "Ни на каком, он не музыкант"}, "correct": "a"}, {"n": 4, "question": "Кем Женя мечтает стать, посвятив себя брату?", "opts": {"a": "Известной актрисой", "b": "Сестрой гения, прославиться через его талант", "c": "Учёным", "d": "Спортсменкой"}, "correct": "b"}, {"n": 5, "question": "Что Женя делает из ревности к сопернице Алине?", "opts": {"a": "Врёт, что концерт брата отменён, и что у него есть невеста Лиля", "b": "Помогает Алине подружиться с братом", "c": "Ничего не делает", "d": "Уезжает из города"}, "correct": "a"}]}, {"grade": 7, "n": 28, "title": "Волшебная шапка", "author": "Худайберды Тухтабаев", "questions": [{"n": 1, "question": "Как зовут главного героя-мальчика в этой сказочной повести?", "opts": {"a": "Хашим (Хашимджан)", "b": "Алладин", "c": "Санчо", "d": "Гулям"}, "correct": "a"}, {"n": 2, "question": "Каким мальчиком Хашим показан в начале повести — трудолюбивым или ленивым?", "opts": {"a": "Очень трудолюбивым и послушным", "b": "Ленивым и бесшабашным разгильдяем", "c": "Слабым и болезненным", "d": "Взрослым не по годам"}, "correct": "b"}, {"n": 3, "question": "Какая волшебная вещь попадает в руки Хашима?", "opts": {"a": "Волшебная шапка, исполняющая любое желание", "b": "Ковёр-самолёт", "c": "Волшебная лампа", "d": "Меч-кладенец"}, "correct": "a"}, {"n": 4, "question": "Какое произведение и в каком году получило премию на Всесоюзном конкурсе на лучшую детскую книгу?", "opts": {"a": "«Волшебная шапка», в 1970 году", "b": "«Волшебная шапка» не получала наград", "c": "Другое произведение того же автора", "d": "Премия была получена в XXI веке"}, "correct": "a"}, {"n": 5, "question": "К какому выводу в итоге приходит Хашим после всех странствий и приключений?", "opts": {"a": "Что без труда и знаний человек ничего не добьётся", "b": "Что магия решает всё без усилий", "c": "Что путешествовать бесполезно", "d": "Ни к какому выводу не приходит"}, "correct": "a"}]}, {"grade": 7, "n": 29, "title": "Пятнадцатилетний капитан", "author": "Жюль Верн", "questions": [{"n": 1, "question": "Как зовут главного героя — пятнадцатилетнего юнгу, который становится капитаном?", "opts": {"a": "Дик Сэнд", "b": "Филеас Фогг", "c": "Джим Хокинс", "d": "Паспарту"}, "correct": "a"}, {"n": 2, "question": "Как называется корабль, на котором происходит действие романа?", "opts": {"a": "«Пилигрим»", "b": "«Наутилус»", "c": "«Испаньола»", "d": "«Санта-Мария»"}, "correct": "a"}, {"n": 3, "question": "Почему Дику Сэнду приходится взять на себя обязанности капитана?", "opts": {"a": "Капитан и вся команда погибли во время охоты на кита", "b": "Капитан просто ушёл в отпуск", "c": "Дик выиграл выборы капитана", "d": "Никаких особых причин"}, "correct": "a"}, {"n": 4, "question": "Кто из членов экипажа оказывается злодеем и намеренно сбивает корабль с курса?", "opts": {"a": "Негоро (судовой кок)", "b": "Миссис Уэлдон", "c": "Сам Дик Сэнд", "d": "Капитан"}, "correct": "a"}, {"n": 5, "question": "Куда в итоге по вине злодея попадает корабль вместо Америки?", "opts": {"a": "В Африку, где герои сталкиваются с работорговцами", "b": "В Австралию", "c": "Прямо домой без происшествий", "d": "На необитаемый остров без людей"}, "correct": "a"}]}, {"grade": 7, "n": 30, "title": "Наша семья", "author": "Бауыржан Момышулы", "questions": [{"n": 1, "question": "Произведение в основном посвящено чему — вымышленной истории или собственной семье автора?", "opts": {"a": "Вымышленной истории, не связанной с автором", "b": "Собственной семье автора, его происхождению и воспитанию", "c": "Истории чужой семьи из другой страны", "d": "Научному исследованию"}, "correct": "b"}, {"n": 2, "question": "Кто из членов семьи, известная как сказительница, знавшая множество традиций, воспитывала автора?", "opts": {"a": "Бабушка Кыztумас", "b": "Соседка", "c": "Учительница", "d": "Никто не воспитывал"}, "correct": "a"}, {"n": 3, "question": "Каким мастером — по роду занятий — был отец автора?", "opts": {"a": "Многоремесленным умельцем: плотником, ювелиром, сапожником", "b": "Только воином", "c": "Только торговцем", "d": "Только чиновником"}, "correct": "a"}, {"n": 4, "question": "В каком возрасте автор потерял мать?", "opts": {"a": "В три года", "b": "В пятнадцать лет", "c": "Он не потерял мать", "d": "В младенчестве, сразу после рождения"}, "correct": "a"}, {"n": 5, "question": "Какую ценность произведение раскрывает помимо личной истории автора?", "opts": {"a": "Только личные переживания без общего смысла", "b": "Национальные традиции, обычаи и мировоззрение казахского народа", "c": "Только военную тактику", "d": "Только географию Казахстана"}, "correct": "b"}]}, {"grade": 8, "n": 1, "title": "Ұшқан ұя", "author": "Бауыржан Момышұлы", "questions": [{"n": 1, "question": "«Ұшқан ұя» шығармасы қандай жанрда жазылған?", "opts": {"a": "Ғылыми фантастика", "b": "Автордың өз балалық шағы туралы мемуарлық (естелік) шығарма", "c": "Детектив романы", "d": "Ертегі"}, "correct": "b"}, {"n": 2, "question": "Шығармада Бауыржанды кім тәрбиелеген — оқиғада ерекше орын алатын кейіпкер кім?", "opts": {"a": "Әжесі Қызтумас", "b": "Патша", "c": "Мұғалімі", "d": "Көршісі"}, "correct": "a"}, {"n": 3, "question": "Бауыржанның әкесі қандай кәсіптермен айналысқан шебер адам болған?", "opts": {"a": "Тек мал шаруашылығымен", "b": "Ағаш ұста, зергер, етікші — көп өнерлі шебер", "c": "Тек саудагер", "d": "Тек әскери адам"}, "correct": "b"}, {"n": 4, "question": "Бауыржан үш жасқа келгенде отбасында қандай қайғылы оқиға болды?", "opts": {"a": "Анасы Рәзия қайтыс болды", "b": "Үйі өртенді", "c": "Ауылдан көшті", "d": "Ешбір оқиға болмады"}, "correct": "a"}, {"n": 5, "question": "Шығарма қазақ халқының қандай тұрмыс-салтын да толық бейнелейді, соған қоса мемуар да болып саналады?", "opts": {"a": "Тек қазіргі заман өмірін", "b": "Дәстүр, ғұрып, ұлттық дүниетанымды (этнографиялық сипатта)", "c": "Тек ғарыш тақырыбын", "d": "Тек шет елдер тұрмысын"}, "correct": "b"}]}, {"grade": 8, "n": 2, "title": "Көшпенділер: Алмас қылыш", "author": "Ілияс Есенберлин", "questions": [{"n": 1, "question": "«Көшпенділер» неше кітаптан тұратын трилогия?", "opts": {"a": "Екі", "b": "Үш («Алмас қылыш», «Жанталас», «Қаһар»)", "c": "Бес", "d": "Он"}, "correct": "b"}, {"n": 2, "question": "«Алмас қылыш» романы негізінен қандай тарихи оқиғаны — қазақ хандығының қай кезеңін — суреттейді?", "opts": {"a": "ХХ ғасырдағы Кеңес дәуірін", "b": "XV ғасырда Керей мен Жәнібектің Әбілқайырдан бөлініп, Қазақ хандығын құруын", "c": "Қазіргі тәуелсіздік жылдарын", "d": "Ежелгі Рим тарихын"}, "correct": "b"}, {"n": 3, "question": "Романда қандай атақты монғол ханының ел билеу туралы даналық сөзі келтіріледі?", "opts": {"a": "Шыңғысханның", "b": "Наполеонның", "c": "Әбілқайырдың", "d": "Абылайдың"}, "correct": "a"}, {"n": 4, "question": "Трилогия қазақ тарихының қандай кезеңдерін қамтиды (шамамен)?", "opts": {"a": "Тек бір ғасырды", "b": "XV ғасырдан Кенесары ханның қазасына дейінгі бес ғасырды", "c": "Тек 10 жылды", "d": "Тек қазіргі заманды"}, "correct": "b"}, {"n": 5, "question": "Роман авторы Ілияс Есенберлин қазақ әдебиетінде негізінен қандай жазушы ретінде танымал?", "opts": {"a": "Тарихи роман жанрын дамытқан жазушы", "b": "Тек ақын ретінде", "c": "Тек драматург ретінде", "d": "Тек аудармашы ретінде"}, "correct": "a"}]}, {"grade": 8, "n": 3, "title": "Шұғаның белгісі", "author": "Бейімбет Майлин", "questions": [{"n": 1, "question": "Шұға кімнің қызы?", "opts": {"a": "Жаппас Есімбек байдың", "b": "Хандың", "c": "Мұғалімнің", "d": "Саудагердің"}, "correct": "a"}, {"n": 2, "question": "Шұға ауыл сыртындағы алтыбақанда алдымен кіммен танысып, ғашық болады?", "opts": {"a": "Әбдірахманмен", "b": "Қасыммен", "c": "Патшамен", "d": "Аңшымен"}, "correct": "a"}, {"n": 3, "question": "Шұға мен Әбдірахман кездесулері сиреп кеткенде бір-бірімен қалай хабарласады?", "opts": {"a": "Тек хат арқылы", "b": "Тек телефон арқылы", "c": "Ешқашан хабарласпайды", "d": "Үшінші адам арқылы ғана"}, "correct": "a"}, {"n": 4, "question": "Шығарма қандай аяқталады — қуанышты ма, әлде қайғылы ма?", "opts": {"a": "Қуанышты, үйлену тойымен", "b": "Қайғылы, Шұғаның қазасымен және оның басына белгі қойылуымен", "c": "Ешбір аяқталуы жоқ, ашық қалады", "d": "Комедиялық түрде аяқталады"}, "correct": "b"}, {"n": 5, "question": "Повесть негізінен қандай әлеуметтік тақырыпты көтереді?", "opts": {"a": "Ғылыми жаңалықтарды", "b": "Салт-дәстүрдің қыз тағдырына салған шектеуі мен махаббат еркіндігінің тартысын", "c": "Спорттық жарыстарды", "d": "Саяхат тәжірибесін"}, "correct": "b"}]}, {"grade": 8, "n": 4, "title": "Қаһарлы күндер", "author": "Тахауи Ахтанов", "questions": [{"n": 1, "question": "Роман қай соғысты тақырып еткен?", "opts": {"a": "Азамат соғысын", "b": "Екінші дүниежүзілік (Ұлы Отан) соғысын", "c": "Кореа соғысын", "d": "Ешбір соғысты"}, "correct": "b"}, {"n": 2, "question": "Романда қандай ірі шайқас — қай қаланың түбіндегі шайқас — суреттеледі?", "opts": {"a": "Мәскеу түбіндегі шайқас", "b": "Париж түбіндегі шайқас", "c": "Токио түбіндегі шайқас", "d": "Ешбір шайқас жоқ"}, "correct": "a"}, {"n": 3, "question": "Романда генерал Панферов басқарған қандай әскери бөлімше ерлігі баяндалады?", "opts": {"a": "Дивизия", "b": "Жалғыз жауынгер", "c": "Теңіз флоты", "d": "Авиация полкі"}, "correct": "a"}, {"n": 4, "question": "Роман кейіпкерлерінің бірі, взвод командирінің есімі кім?", "opts": {"a": "Ержан", "b": "Асан", "c": "Дархан", "d": "Болат"}, "correct": "a"}, {"n": 5, "question": "Роман авторы Тахауи Ахтанов бұл романды қашан жазған және ол қандай тұңғыш романы болды?", "opts": {"a": "1956 жылы, оның тұңғыш романы", "b": "2000 жылы, соңғы шығармасы", "c": "Романды жазбаған, тек аударған", "d": "1917 жылы"}, "correct": "a"}]}, {"grade": 8, "n": 5, "title": "Мен — Малаламын", "author": "Малала Юсуфзай", "questions": [{"n": 1, "question": "Малала Юсуфзай қай елден шыққан қыз?", "opts": {"a": "Пәкістаннан", "b": "Үндістаннан", "c": "Ауғанстаннан", "d": "Ираннан"}, "correct": "a"}, {"n": 2, "question": "Малала неліктен әлемге танымал болды — қандай құқық үшін күресті?", "opts": {"a": "Спорт үшін", "b": "Қыздардың білім алу құқығы үшін", "c": "Саяси билік үшін", "d": "Байлық үшін"}, "correct": "b"}, {"n": 3, "question": "Малала қандай оқиғадан кейін бүкіл әлемге танымал болды?", "opts": {"a": "Спорт жарысында жеңіске жеткеннен кейін", "b": "Талибан content боевигінің оны атып кетуінен аман қалғаннан кейін", "c": "Кино түсіргеннен кейін", "d": "Ешбір оқиға болмаған"}, "correct": "b"}, {"n": 4, "question": "Малала қандай халықаралық сыйлықтың ең жас лауреаты атанды?", "opts": {"a": "Нобель сыйлығының (Бейбітшілік)", "b": "Оскар сыйлығының", "c": "Грэмми сыйлығының", "d": "Пулитцер сыйлығының"}, "correct": "a"}, {"n": 5, "question": "Кітап негізінен қандай жанрда жазылған?", "opts": {"a": "Ғылыми фантастика", "b": "Автордың өз өмірі туралы мемуарлық шығарма", "c": "Ертегі", "d": "Детектив"}, "correct": "b"}]}, {"grade": 8, "n": 6, "title": "Түнде атылған оқ", "author": "Кемел Тоқаев", "questions": [{"n": 1, "question": "Автор Кемел Тоқаев қазақ әдебиетінде негізінен қандай жанрдың негізін салушы саналады?", "opts": {"a": "Детективтік-шытырман оқиғалы прозаның", "b": "Балалар ертегісінің", "c": "Ғылыми фантастиканың", "d": "Драма пьесаларының"}, "correct": "a"}, {"n": 2, "question": "Кемел Тоқаевтың шығармалары негізінен нені баяндайды?", "opts": {"a": "Тек махаббат тақырыбын", "b": "Тылдағы партизандардың ерлігі мен милиция қызметкерлерінің қылмыс ашудағы еңбегін", "c": "Тек ғарышты игеруді", "d": "Тек спорт жарыстарын"}, "correct": "b"}, {"n": 3, "question": "Автордың өз өмірінде майданда болған тәжірибесі шығармашылығына қалай әсер етті?", "opts": {"a": "Ешбір әсері болмады", "b": "Ол өзі майданда болып, жараланған, бұл оның қаһармандық тақырыпқа баруына негіз болды", "c": "Ол ешқашан майданда болмаған", "d": "Ол тек ертегі жазған"}, "correct": "b"}, {"n": 4, "question": "«Түнде атылған оқ» қандай циклдегі повестердің бірі («Ерекше тапсырма», «Құпия ізі» қатарлас)?", "opts": {"a": "Тоқаевтың детективтік-приключен повестер циклінің", "b": "Ғылыми мақалалар циклінің", "c": "Өлеңдер жинағының", "d": "Балалар ертегілер циклінің"}, "correct": "a"}, {"n": 5, "question": "Мұндай шығармалар негізінен қандай құндылықты дәріптейді?", "opts": {"a": "Тек қорқақтықты", "b": "Ерлік, батылдық және заң тәртібін сақтаудағы табандылықты", "c": "Тек байлыққа құмарлықты", "d": "Ешбір құндылықты дәріптемейді"}, "correct": "b"}]}, {"grade": 8, "n": 7, "title": "Мұзтау", "author": "Оралхан Бокей", "questions": [{"n": 1, "question": "Повестің бас кейіпкері кім деп аталады?", "opts": {"a": "Ақтан", "b": "Серік", "c": "Дәурен", "d": "Болат"}, "correct": "a"}, {"n": 2, "question": "Ақтан балалық шағынан бері негізінен қандай малмен (аңмен) тығыз байланыста өседі?", "opts": {"a": "Жылқымен", "b": "Бұғылармен", "c": "Түйемен", "d": "Қойлармен"}, "correct": "b"}, {"n": 3, "question": "Ақтанның әкесі не болған, ол неге жалғыз қалды?", "opts": {"a": "Соғыстан оралмаған", "b": "Қалаға көшіп кетті", "c": "Ешқашан болмаған", "d": "Аңшылықта қаза тапты (басқа себеп)"}, "correct": "a"}, {"n": 4, "question": "Ауылды тастап кетпей, Ақтан қандай қызмет атқаруға кіріседі?", "opts": {"a": "Мұғалім болады", "b": "Ауыл күзетшісі болады", "c": "Дәрігер болады", "d": "Милиция болады"}, "correct": "b"}, {"n": 5, "question": "Повестегі қосымша желіде біреу үңгірде жасырылған нені іздейді?", "opts": {"a": "Жасырын қазынаны", "b": "Жоғалған малды", "c": "Ежелгі қолжазбаны", "d": "Су көзін"}, "correct": "a"}]}, {"grade": 8, "n": 8, "title": "Том Сойердің басынан кешкендері", "author": "Марк Твен", "questions": [{"n": 1, "question": "Оқиға қай өзен жағасындағы қалашықта өтеді?", "opts": {"a": "Миссисипи өзені жағасында", "b": "Ніл өзені жағасында", "c": "Еділ өзені жағасында", "d": "Теңіз жағасында"}, "correct": "a"}, {"n": 2, "question": "Том Сойер қоршауды бояу ісін қалай шешеді — өзі бояп бітіре ме, әлде басқаларды қалай көндіреді?", "opts": {"a": "Өзі жалғыз бояп бітіреді", "b": "Айла жасап, басқа балаларды бояуды артықшылық деп сеніп, өзіне бояттырады", "c": "Қоршауды мүлде боямайды", "d": "Әкесіне бояттырады"}, "correct": "b"}, {"n": 3, "question": "Томның ең жақын досының есімі кім?", "opts": {"a": "Гекльберри Финн", "b": "Шерлок Холмс", "c": "Робинзон Крузо", "d": "Оливер Твист"}, "correct": "a"}, {"n": 4, "question": "Роман барысында Том мен Бекки қандай қауіпті жағдайға тап болады?", "opts": {"a": "Үңгірде адасып қалады", "b": "Кемеде суға кетеді", "c": "Тауда қар көшкінінде қалады", "d": "Ешбір қауіпті жағдай болмайды"}, "correct": "a"}, {"n": 5, "question": "Том мен досы ақыр соңында қандай қазына табады?", "opts": {"a": "Қарақшылар жасырған алтын тиындарды", "b": "Ежелгі қолжазбаларды", "c": "Қару-жарақты", "d": "Ешнәрсе таппайды"}, "correct": "a"}]}, {"grade": 8, "n": 9, "title": "Гулливердің саяхаттары", "author": "Джонатан Свифт", "questions": [{"n": 1, "question": "Гулливер алғашқы саяхатында қандай ел — алыптар елі ме, әлде ергежейлілер елі ме — тап болады?", "opts": {"a": "Ергежейлілер елі — Лилипутия", "b": "Алыптар елі", "c": "Тек өз елінде қалады", "d": "Роботтар елі"}, "correct": "a"}, {"n": 2, "question": "Гулливер екінші саяхатында қандай елге тап болады?", "opts": {"a": "Алыптар елі — Бробдингнег", "b": "Лилипутия", "c": "Су асты елі", "d": "Ай әлемі"}, "correct": "a"}, {"n": 3, "question": "Роман негізінен қандай әдеби тәсіл арқылы сол кездегі қоғамды сынайды?", "opts": {"a": "Тікелей ғылыми мақаламен", "b": "Сатира мен әсірелеу (гипербола) арқылы", "c": "Ешбір сынау жоқ", "d": "Тек статистикамен"}, "correct": "b"}, {"n": 4, "question": "Гулливер қандай кәсіппен айналысатын адам ретінде суреттеледі?", "opts": {"a": "Дәрігер әрі кеме капитаны", "b": "Патша", "c": "Аңшы", "d": "Суретші"}, "correct": "a"}, {"n": 5, "question": "Роман қандай жанрда жазылған?", "opts": {"a": "Ғылыми-фантастикалық сатиралық саяхат романы", "b": "Ғашықтық драма", "c": "Тарихи хроника", "d": "Детектив"}, "correct": "a"}]}, {"grade": 8, "n": 10, "title": "Дос табу және адамдарға ықпал ету өнері", "author": "Дейл Карнеги", "questions": [{"n": 1, "question": "Кітап негізінен қандай жанрда жазылған?", "opts": {"a": "Көркем әңгіме", "b": "Адами қарым-қатынас пен қарым-қатынас өнеріне арналған танымдық/өзін-өзі дамыту кітабы", "c": "Ғылыми-фантастика романы", "d": "Тарихи хроника"}, "correct": "b"}, {"n": 2, "question": "Кітапта Карнеги адамдарға ықпал етудің қандай негізгі принципін ұсынады?", "opts": {"a": "Адамдарды сынауды, кінәлауды және шағымдануды болдырмау", "b": "Әрдайым қатаң сынау", "c": "Ешкіммен қарым-қатынас жасамау", "d": "Тек бұйрық беру"}, "correct": "a"}, {"n": 3, "question": "Кітап қай ғасырда алғаш жарық көрген — ХХ ғасырдың басында ма, әлде ортасында ма?", "opts": {"a": "1930-жылдары (ХХ ғасырдың басы-ортасы)", "b": "2020 жылы", "c": "XIX ғасырда", "d": "Ежелгі заманда"}, "correct": "a"}, {"n": 4, "question": "Кітаптың негізгі мақсаты — оқырманға нені үйрету?", "opts": {"a": "Тек ақша табу тәсілдерін", "b": "Адамдармен тиімді қарым-қатынас орнатып, шынайы достық пен ықпалды қалай құру керектігін", "c": "Тек шетел тілдерін үйрету", "d": "Тек спорттық жаттығуларды"}, "correct": "b"}, {"n": 5, "question": "Автор Дейл Карнеги негізінен қандай саланың классигі саналады?", "opts": {"a": "Өзін-өзі дамыту мен қарым-қатынас психологиясының", "b": "Физика ғылымының", "c": "Әдеби сынның", "d": "Астрономияның"}, "correct": "a"}]}, {"grade": 8, "n": 11, "title": "Сақиналар әміршісі: сақина бауырластығы", "author": "Джон Рональд Руэл Толкин", "questions": [{"n": 1, "question": "Бас кейіпкер хоббит Фродо Бэггинске қандай қауіпті зат мұраға қалады?", "opts": {"a": "Сиқырлы қылыш", "b": "Жалғыз сақина", "c": "Алтын тәж", "d": "Сиқырлы кітап"}, "correct": "b"}, {"n": 2, "question": "Фродоға сақинаны жоюға көмектесуге ант берген серіктестік неше мүшеден тұрады?", "opts": {"a": "Тоғыз серіктестен («Сақина бауырластығы»)", "b": "Бір адамнан", "c": "Жүзден", "d": "Екеуден"}, "correct": "a"}, {"n": 3, "question": "Сақинаны жоюдың жалғыз жолы қайда — қандай жанартауда — жатыр?", "opts": {"a": "Ақыретгүл тауында (Ору мор жанартауында)", "b": "Эверест тауында", "c": "Везувий жанартауында", "d": "Ешбір жанартауда емес"}, "correct": "a"}, {"n": 4, "question": "Серіктестікке жетекшілік ететін дана сиқыршының есімі кім?", "opts": {"a": "Гэндальф", "b": "Саурон", "c": "Саруман", "d": "Гимли"}, "correct": "a"}, {"n": 5, "question": "Роман қандай жанрда жазылған?", "opts": {"a": "Эпикалық фэнтези", "b": "Детектив", "c": "Ғылыми фантастика", "d": "Комедия"}, "correct": "a"}]}, {"grade": 8, "n": 12, "title": "Гауһартас", "author": "Дулат Исабеков", "questions": [{"n": 1, "question": "Повесть оқиғасы негізінен қай жерде — Алматы облысындағы ауылда ма — өтеді?", "opts": {"a": "Теңіз жағасында", "b": "Алматы облысындағы қарапайым ауылда", "c": "Астанада", "d": "Шетелде"}, "correct": "b"}, {"n": 2, "question": "Повестің басты кейіпкерлерінің бірі, әкесіне мінез-құлқы жағынан ұқсас жас жігіттің есімі кім?", "opts": {"a": "Ыбыш", "b": "Асан", "c": "Дархан", "d": "Мұрат"}, "correct": "a"}, {"n": 3, "question": "Повесть негізінен қандай тақырыпты — ағайынды екеудің әртүрлі тәрбие алу нәтижесін — көтереді?", "opts": {"a": "Ғарыш тақырыбын", "b": "Екі бауырдың екі түрлі тәрбиенің салдарынан қалыптасқан мінез қайшылығын", "c": "Спорт тақырыбын", "d": "Соғыс тақырыбын"}, "correct": "b"}, {"n": 4, "question": "Повесть қашан жазылған?", "opts": {"a": "1967 жылы", "b": "2020 жылы", "c": "1900 жылы", "d": "Жазылу жылы белгісіз"}, "correct": "a"}, {"n": 5, "question": "Повесть соңында басты әйел кейіпкер Салтанаттың тағдыры қалай шешіледі?", "opts": {"a": "Ол бақытты өмір сүреді", "b": "Ол қайтыс болады, бұл болашаққа деген үмітті білдіреді", "c": "Ол шетелге кетеді", "d": "Ол ешқашан пайда болмайды"}, "correct": "b"}]}, {"grade": 8, "n": 13, "title": "Ақиқат пен аңыз", "author": "Әзілхан Нұршайықов", "questions": [{"n": 1, "question": "Роман-диалог қай атақты қаһарманның өмірін баяндайды?", "opts": {"a": "Бауыржан Момышұлының", "b": "Абылай ханның", "c": "Қажымұқанның", "d": "Абайдың"}, "correct": "a"}, {"n": 2, "question": "Шығарма қандай ерекше формада — диалог түрінде ме — жазылған?", "opts": {"a": "Роман-диалог (сұхбат түрінде)", "b": "Өлең түрінде", "c": "Пьеса түрінде", "d": "Күнделік түрінде"}, "correct": "a"}, {"n": 3, "question": "Романда Бауыржан Момышұлы туралы қандай екі ұғым — шындық пен аңыз — ұштастырылады?", "opts": {"a": "Ақиқат (шындық фактілер) пен халық арасында тараған аңыз-әңгімелер", "b": "Тек ғылыми деректер", "c": "Тек ойдан шығарылған оқиғалар", "d": "Ешбір ұғым ұштастырылмайды"}, "correct": "a"}, {"n": 4, "question": "Бауыржан Момышұлы туралы алғаш кең таныған қандай орыс жазушысының романы болды?", "opts": {"a": "Александр Бектің «Волоколам тас жолы»", "b": "Толстойдың «Соғыс пен бейбітшілігі»", "c": "Пушкиннің романы", "d": "Достоевскийдің романы"}, "correct": "a"}, {"n": 5, "question": "Роман қашан жеке кітап болып жарық көрген?", "opts": {"a": "1978 жылы", "b": "2020 жылы", "c": "1900 жылы", "d": "Ешқашан жарық көрмеген"}, "correct": "a"}]}, {"grade": 8, "n": 14, "title": "Қаныштың жастық шағы", "author": "Төкен Оразов", "questions": [{"n": 1, "question": "Кітап қазақтың атақты ғалымы, геолог-академигі Қанышты — толық атымен кімді айтады?", "opts": {"a": "Қаныш Сәтбаевты", "b": "Қаныш Иманбаевты", "c": "Қаныш Байтұрсынұлын", "d": "Қаныш Жұбановты"}, "correct": "a"}, {"n": 2, "question": "Шығарма Қанышты өмірінің қай кезеңінде — есейгенде ме, әлде жас/бала кезінде бе — суреттейді?", "opts": {"a": "Кәрілік шағында", "b": "Жастық/бала кезінде", "c": "Тек өлген күнінде", "d": "Тек студент кезінде ғана"}, "correct": "b"}, {"n": 3, "question": "Қаныш Сәтбаев кейінірек қандай саладағы ғалым ретінде танымал болды?", "opts": {"a": "Медицина", "b": "Геология (жер қойнауын зерттеу)", "c": "Астрономия", "d": "Тіл білімі"}, "correct": "b"}, {"n": 4, "question": "Қаныш Сәтбаев есімімен байланысты қандай кен орны әйгілі?", "opts": {"a": "Жезқазған мыс кен орны", "b": "Теңіз түбіндегі мұнай кені", "c": "Алтын кені Балқашта", "d": "Көмір кені Қарағандыда ғана"}, "correct": "a"}, {"n": 5, "question": "Мұндай өмірбаяндық шығармалар оқырманға негізінен нені көрсетуге бағытталған?", "opts": {"a": "Тек тарихи датаны жаттауды", "b": "Ұлы адамдардың бала кезден еңбекқорлық пен ізденіске бейімділігін", "c": "Тек ғылыми терминдерді", "d": "Тек географиялық атауларды"}, "correct": "b"}]}, {"grade": 8, "n": 15, "title": "Интернат наны", "author": "Шерхан Мұртаза", "questions": [{"n": 1, "question": "Әңгіме оқиғасы қай кезеңдегі — соғыстан кейінгі интернат өмірін баяндайды?", "opts": {"a": "Соғыстан кейінгі жылдардағы интернат өмірін", "b": "Қазіргі заман мектебін", "c": "Хандық дәуірді", "d": "Ғарыш кезеңін"}, "correct": "a"}, {"n": 2, "question": "Әңгіменің бас кейіпкері, тамаққа тоймайтын бала кім деп аталады?", "opts": {"a": "Әлтай", "b": "Асан", "c": "Ерлан", "d": "Дархан"}, "correct": "a"}, {"n": 3, "question": "Балалар түсінде негізінен нені — қандай тағамды — армандайды?", "opts": {"a": "Ауылдың нарт қызыл таба нанын", "b": "Шоколадты", "c": "Мұзқаймақты", "d": "Еттi"}, "correct": "a"}, {"n": 4, "question": "Әңгіме негізінен қандай тақырыпты — нанның қадірін — ұғындырады?", "opts": {"a": "Спорттың пайдасын", "b": "Соғыстан кейінгі тапшылық заманда нанның қадірі мен қиыншылықты", "c": "Ғылыми жаңалықтарды", "d": "Саяхатты"}, "correct": "b"}, {"n": 5, "question": "Автор Шерхан Мұртазаның балалық шағы қандай кезеңмен тұспа-тұс келді?", "opts": {"a": "Соғыс жылдарымен", "b": "Тәуелсіздік жылдарымен", "c": "ХХІ ғасырмен", "d": "Ешбір қиын кезеңмен тұспа-тұс келмеді"}, "correct": "a"}]}, {"grade": 8, "n": 16, "title": "Наша семья", "author": "Бауыржан Момышулы", "questions": [{"n": 1, "question": "Произведение в основном посвящено чему — вымышленной истории или собственной семье автора?", "opts": {"a": "Вымышленной истории, не связанной с автором", "b": "Собственной семье автора, его происхождению и воспитанию", "c": "Истории чужой семьи из другой страны", "d": "Научному исследованию"}, "correct": "b"}, {"n": 2, "question": "Кто из членов семьи, известная как сказительница, знавшая множество традиций, воспитывала автора?", "opts": {"a": "Бабушка Кыztумас", "b": "Соседка", "c": "Учительница", "d": "Никто не воспитывал"}, "correct": "a"}, {"n": 3, "question": "Каким мастером — по роду занятий — был отец автора?", "opts": {"a": "Многоремесленным умельцем: плотником, ювелиром, сапожником", "b": "Только воином", "c": "Только торговцем", "d": "Только чиновником"}, "correct": "a"}, {"n": 4, "question": "В каком возрасте автор потерял мать?", "opts": {"a": "В три года", "b": "В пятнадцать лет", "c": "Он не потерял мать", "d": "В младенчестве, сразу после рождения"}, "correct": "a"}, {"n": 5, "question": "Какую ценность произведение раскрывает помимо личной истории автора?", "opts": {"a": "Только личные переживания без общего смысла", "b": "Национальные традиции, обычаи и мировоззрение казахского народа", "c": "Только военную тактику", "d": "Только географию Казахстана"}, "correct": "b"}]}, {"grade": 8, "n": 17, "title": "Горький запах полыни", "author": "Саин Муратбеков", "questions": [{"n": 1, "question": "В каком году и в каком возрасте появляется в ауле главный герой Аян?", "opts": {"a": "Весной 1942 года, примерно 10-12 лет", "b": "В 2000 году, взрослым мужчиной", "c": "Летом 1941 года, младенцем", "d": "Никогда не появляется в ауле"}, "correct": "a"}, {"n": 2, "question": "Какая особенность есть у Аяна — почему он не может, как все, бегать и играть?", "opts": {"a": "Он хромой (травма ноги)", "b": "Он слепой", "c": "Он глухой", "d": "У него нет особенностей"}, "correct": "a"}, {"n": 3, "question": "Чем Аян помогает местным детям справляться с тяготами военного времени?", "opts": {"a": "Даёт им еду", "b": "Рассказывает сказки", "c": "Учит их драться", "d": "Ничем не помогает"}, "correct": "b"}, {"n": 4, "question": "Что происходит с Аяном после того, как он узнаёт о гибели отца на фронте?", "opts": {"a": "Он остаётся в ауле навсегда", "b": "Уезжает в детский дом", "c": "Убегает на фронт", "d": "Ничего не меняется"}, "correct": "b"}, {"n": 5, "question": "Что символизирует горький запах полыни в повести?", "opts": {"a": "Запах, исходящий от одежды отцов и братьев, ушедших на фронт — символ разлуки и войны", "b": "Запах степных цветов, не связанный с войной", "c": "Запах готовки в ауле", "d": "Ничего не символизирует"}, "correct": "a"}]}, {"grade": 8, "n": 18, "title": "Ночной выстрел", "author": "Кемель Токаев", "questions": [{"n": 1, "question": "В каком жанре в основном писал автор Кемель Токаев большинство своих произведений?", "opts": {"a": "Любовная лирика", "b": "Детективно-приключенческая проза", "c": "Комедия", "d": "Сказки для малышей"}, "correct": "b"}, {"n": 2, "question": "Каким автор считается в истории казахской литературы?", "opts": {"a": "Основоположником детективного жанра в казахской литературе", "b": "Основателем научной фантастики", "c": "Первым казахским поэтом", "d": "Автором только детских сказок"}, "correct": "a"}, {"n": 3, "question": "О чём в основном рассказывают повести Токаева, включая «Ночной выстрел»?", "opts": {"a": "О подвигах партизан в тылу врага и работе органов правопорядка в раскрытии преступлений", "b": "Только о любовных драмах", "c": "Только о путешествиях по миру", "d": "Только о жизни животных"}, "correct": "a"}, {"n": 4, "question": "Каким был жизненный опыт самого автора, повлиявший на его творчество?", "opts": {"a": "Он был военным сержантом на фронте, был несколько раз ранен", "b": "Он никогда не покидал город", "c": "Он был только учителем", "d": "Он был врачом"}, "correct": "a"}, {"n": 5, "question": "К какому более широкому жанровому направлению относится большинство произведений Токаева?", "opts": {"a": "Детектив и приключения", "b": "Пастораль", "c": "Мемуары о путешествиях", "d": "Юмористические рассказы"}, "correct": "a"}]}, {"grade": 8, "n": 19, "title": "7 навыков высокоэффективных подростков", "author": "Шон Кови", "questions": [{"n": 1, "question": "В каком жанре в основном написана эта книга?", "opts": {"a": "Художественный рассказ", "b": "Мотивационная книга по саморазвитию для подростков", "c": "Научная фантастика", "d": "Историческая хроника"}, "correct": "b"}, {"n": 2, "question": "Чью концепцию «7 навыков» автор Шон Кови адаптировал специально для подростков?", "opts": {"a": "Концепцию своего отца Стивена Кови", "b": "Полностью новую, никем не использованную концепцию", "c": "Концепцию Дейла Карнеги", "d": "Концепцию Наполеона Хилла"}, "correct": "a"}, {"n": 3, "question": "Что означает навык «Будь проактивным» в книге?", "opts": {"a": "Просто ждать и ничего не делать", "b": "Самостоятельно делать выбор в ответ на обстоятельства, проявлять инициативу", "c": "Слушать только других", "d": "Ни с кем не считаться"}, "correct": "b"}, {"n": 4, "question": "С какой целью написана эта книга для подросткового читателя?", "opts": {"a": "Только для развлечения", "b": "Помочь подросткам сформировать эффективные привычки для успеха в жизни", "c": "Только для изучения истории", "d": "Только для изучения языков"}, "correct": "b"}, {"n": 5, "question": "На сколько основных групп делятся навыки в концепции (личная победа, общественная победа)?", "opts": {"a": "Только на одну", "b": "На две основные группы", "c": "На десять групп", "d": "Навыки не делятся на группы"}, "correct": "b"}]}, {"grade": 8, "n": 20, "title": "Суровые дни", "author": "Тахави Ахтанов", "questions": [{"n": 1, "question": "Роман посвящён какой войне?", "opts": {"a": "Гражданской войне", "b": "Великой Отечественной войне", "c": "Корейской войне", "d": "Ни одной войне"}, "correct": "b"}, {"n": 2, "question": "Какое крупное сражение — под каким городом — описано в романе?", "opts": {"a": "Сражение под Москвой", "b": "Сражение под Парижем", "c": "Сражение под Токио", "d": "Никакого сражения нет"}, "correct": "a"}, {"n": 3, "question": "Действия какой дивизии, под командованием какого генерала, описаны в романе?", "opts": {"a": "Дивизии генерала Панферова", "b": "Дивизии генерала Жукова", "c": "Отдельного взвода без командира", "d": "Морского флота"}, "correct": "a"}, {"n": 4, "question": "Как зовут одного из героев романа, командира взвода?", "opts": {"a": "Ержан", "b": "Иван", "c": "Пётр", "d": "Сергей"}, "correct": "a"}, {"n": 5, "question": "В каком году был написан и опубликован этот, первый роман автора?", "opts": {"a": "В 1956 году", "b": "В 2000 году", "c": "Роман не публиковался", "d": "В 1917 году"}, "correct": "a"}]}, {"grade": 8, "n": 21, "title": "Белый пароход", "author": "Чингиз Айтматов", "questions": [{"n": 1, "question": "Главный герой повести — кто он по возрасту?", "opts": {"a": "Маленький мальчик, живущий с дедом", "b": "Пожилой мужчина", "c": "Молодая девушка", "d": "Военный офицер"}, "correct": "a"}, {"n": 2, "question": "В какое животное мечтает превратиться мальчик, чтобы уплыть к отцу?", "opts": {"a": "В рыбу", "b": "В птицу", "c": "В волка", "d": "В оленя"}, "correct": "a"}, {"n": 3, "question": "Как зовут доброго дедушку мальчика, лесника, воплощающего доброту и связь с легендой о Рогатой матери-оленихе?", "opts": {"a": "Момун", "b": "Орозкул", "c": "Сейдахмат", "d": "Кулубек"}, "correct": "a"}, {"n": 4, "question": "Кто из родственников мальчика — жестокий и грубый человек, вызывающий страх у семьи?", "opts": {"a": "Орозкул, муж тёти", "b": "Момун, дед", "c": "Отец мальчика", "d": "Никто из родственников"}, "correct": "a"}, {"n": 5, "question": "Чем в итоге заканчивается повесть — трагично или благополучно?", "opts": {"a": "Трагически: мальчик погибает / исчезает, уплывая рекой", "b": "Мальчик благополучно находит отца", "c": "Ничего не происходит", "d": "Комедийным финалом"}, "correct": "a"}]}, {"grade": 8, "n": 22, "title": "Я — Малала", "author": "Малала Юсуфзай", "questions": [{"n": 1, "question": "Малала Юсуфзай — уроженка какой страны?", "opts": {"a": "Пакистана", "b": "Индии", "c": "Афганистана", "d": "Ирана"}, "correct": "a"}, {"n": 2, "question": "За какое право Малала боролась, что сделало её всемирно известной?", "opts": {"a": "За право женщин на спорт", "b": "За право девочек на образование", "c": "За политическую власть", "d": "За богатство"}, "correct": "b"}, {"n": 3, "question": "После какого события Малала стала известна на весь мир?", "opts": {"a": "После победы на спортивных соревнованиях", "b": "После того как выжила при покушении боевика движения «Талибан»", "c": "После съёмок в кино", "d": "Никакого особого события не было"}, "correct": "b"}, {"n": 4, "question": "Лауреатом какой премии Малала стала самым молодым человеком в истории?", "opts": {"a": "Нобелевской премии мира", "b": "Оскара", "c": "Грэмми", "d": "Пулитцеровской премии"}, "correct": "a"}, {"n": 5, "question": "В каком жанре написана эта книга?", "opts": {"a": "Научная фантастика", "b": "Автобиографические мемуары", "c": "Сказка", "d": "Детектив"}, "correct": "b"}]}, {"grade": 8, "n": 23, "title": "Кочевники: заговорённый меч", "author": "Ильяс Есенберлин", "questions": [{"n": 1, "question": "Из скольких книг состоит трилогия «Кочевники»?", "opts": {"a": "Из двух", "b": "Из трёх («Заговорённый меч», «Отчаяние», «Хан Кене»)", "c": "Из пяти", "d": "Из десяти"}, "correct": "b"}, {"n": 2, "question": "Какой исторический период отражён в первой книге трилогии — «Заговорённый меч»?", "opts": {"a": "XV век, отделение Керея и Жанибека от Абулхаира и создание Казахского ханства", "b": "XX век, советская эпоха", "c": "Современность", "d": "Древний Рим"}, "correct": "a"}, {"n": 3, "question": "Какая мудрая цитата известного монгольского хана приводится в романе?", "opts": {"a": "Цитата Чингисхана", "b": "Цитата Наполеона", "c": "Цитата Абулхаира", "d": "Цитата Абылая"}, "correct": "a"}, {"n": 4, "question": "Какой временной период в целом охватывает трилогия?", "opts": {"a": "Только один век", "b": "Около пяти веков — от создания ханства до гибели хана Кенесары", "c": "Только 10 лет", "d": "Только современность"}, "correct": "b"}, {"n": 5, "question": "Чем известен автор Ильяс Есенберлин в казахской литературе?", "opts": {"a": "Как основоположник жанра исторического романа", "b": "Только как поэт", "c": "Только как драматург", "d": "Только как переводчик"}, "correct": "a"}]}, {"grade": 8, "n": 24, "title": "Путешествия Гулливера", "author": "Джонатан Свифт", "questions": [{"n": 1, "question": "В какую страну Гулливер попадает во время первого путешествия — страну великанов или лилипутов?", "opts": {"a": "Страну лилипутов — Лилипутию", "b": "Страну великанов", "c": "Остаётся дома", "d": "Страну роботов"}, "correct": "a"}, {"n": 2, "question": "В какую страну Гулливер попадает во втором путешествии?", "opts": {"a": "Страну великанов — Бробдингнег", "b": "Лилипутию", "c": "Подводный мир", "d": "Мир на Луне"}, "correct": "a"}, {"n": 3, "question": "Каким литературным приёмом автор в основном критикует современное ему общество?", "opts": {"a": "Прямой научной статьёй", "b": "Сатирой и преувеличением (гиперболой)", "c": "Никак не критикует", "d": "Только статистикой"}, "correct": "b"}, {"n": 4, "question": "Кем по профессии является сам Гулливер?", "opts": {"a": "Врачом и капитаном корабля", "b": "Королём", "c": "Охотником", "d": "Художником"}, "correct": "a"}, {"n": 5, "question": "В каком жанре написан роман?", "opts": {"a": "Научно-фантастический сатирический роман-путешествие", "b": "Любовная драма", "c": "Историческая хроника", "d": "Детектив"}, "correct": "a"}]}, {"grade": 8, "n": 25, "title": "Властелин колец: Братство кольца", "author": "Джон Р. Р. Толкин", "questions": [{"n": 1, "question": "Какой опасный предмет достаётся в наследство хоббиту Фродо Бэггинсу?", "opts": {"a": "Волшебный меч", "b": "Единое Кольцо", "c": "Золотая корона", "d": "Волшебная книга"}, "correct": "b"}, {"n": 2, "question": "Из скольких членов состоит отряд, поклявшийся помочь Фродо уничтожить Кольцо?", "opts": {"a": "Из девяти («Братство Кольца»)", "b": "Из одного", "c": "Из ста", "d": "Из двух"}, "correct": "a"}, {"n": 3, "question": "Где находится единственное место, где можно уничтожить Кольцо?", "opts": {"a": "В Роковой горе (вулкане Ородруин)", "b": "На Эвересте", "c": "В Везувии", "d": "Нигде, Кольцо нельзя уничтожить"}, "correct": "a"}, {"n": 4, "question": "Как зовут мудрого волшебника, возглавляющего Братство?", "opts": {"a": "Гэндальф", "b": "Саурон", "c": "Саруман", "d": "Гимли"}, "correct": "a"}, {"n": 5, "question": "В каком жанре написан роман?", "opts": {"a": "Эпическое фэнтези", "b": "Детектив", "c": "Научная фантастика", "d": "Комедия"}, "correct": "a"}]}, {"grade": 8, "n": 26, "title": "Стрела Махамбета", "author": "Ануар Алимжанов", "questions": [{"n": 1, "question": "Роман посвящён жизни и творчеству какого казахского поэта?", "opts": {"a": "Махамбета Утемисова", "b": "Абая Кунанбаева", "c": "Джамбула Джабаева", "d": "Ильяса Джансугурова"}, "correct": "a"}, {"n": 2, "question": "Каким считается Махамбет Утемисов в истории казахской литературы?", "opts": {"a": "Основоположником казахской гражданской поэзии", "b": "Первым романистом", "c": "Основателем детектива", "d": "Автором только детских сказок"}, "correct": "a"}, {"n": 3, "question": "Одним из руководителей какого события — против кого — становится Махамбет?", "opts": {"a": "Народного восстания против произвола хана Жангира", "b": "Восстания против джунгар", "c": "Восстания против Наполеона", "d": "Ни одного восстания не возглавлял"}, "correct": "a"}, {"n": 4, "question": "Роман строится на скольких сюжетных линиях — становление поэта и что ещё?", "opts": {"a": "На двух — становление поэта и жизнь простого народа", "b": "Только на одной", "c": "На пяти", "d": "Ни на одной чёткой линии"}, "correct": "a"}, {"n": 5, "question": "В каком году был впервые издан роман?", "opts": {"a": "В 1969 году", "b": "В 2000 году", "c": "В 1800 году", "d": "Роман не издавался"}, "correct": "a"}]}, {"grade": 8, "n": 27, "title": "Как завоевать друзей и оказывать влияние на людей", "author": "Дейл Карнеги", "questions": [{"n": 1, "question": "В каком жанре в основном написана эта книга?", "opts": {"a": "Художественный рассказ", "b": "Научно-популярная книга по саморазвитию и общению", "c": "Научная фантастика", "d": "Историческая хроника"}, "correct": "b"}, {"n": 2, "question": "Какой основной принцип общения с людьми предлагает Карнеги?", "opts": {"a": "Избегать критики, осуждения и жалоб на людей", "b": "Всегда жёстко критиковать", "c": "Не общаться с людьми вообще", "d": "Только отдавать приказы"}, "correct": "a"}, {"n": 3, "question": "Примерно в какое десятилетие книга впервые была опубликована?", "opts": {"a": "В 1930-е годы", "b": "В 2020 году", "c": "В XIX веке", "d": "В древности"}, "correct": "a"}, {"n": 4, "question": "Какова основная цель книги для читателя?", "opts": {"a": "Только заработать деньги", "b": "Научить эффективно общаться с людьми и строить искреннюю дружбу и влияние", "c": "Только выучить иностранные языки", "d": "Только заниматься спортом"}, "correct": "b"}, {"n": 5, "question": "Кем считается автор Дейл Карнеги в своей области?", "opts": {"a": "Классиком психологии саморазвития и общения", "b": "Физиком", "c": "Литературным критиком", "d": "Астрономом"}, "correct": "a"}]}, {"grade": 8, "n": 28, "title": "Истина и легенда", "author": "Азильхан Нуршаихов", "questions": [{"n": 1, "question": "Роман-диалог посвящён жизни какого известного героя?", "opts": {"a": "Бауыржана Момышулы", "b": "Абылай-хана", "c": "Кажымукана", "d": "Абая"}, "correct": "a"}, {"n": 2, "question": "В какой необычной форме написано это произведение?", "opts": {"a": "В форме романа-диалога (интервью)", "b": "В форме стихотворения", "c": "В форме пьесы", "d": "В форме дневника"}, "correct": "a"}, {"n": 3, "question": "Какие два понятия — правду и что ещё — автор сплетает в романе о герое?", "opts": {"a": "Истину (реальные факты) и легенды, ходившие среди народа", "b": "Только научные данные", "c": "Только вымысел", "d": "Ничего не сплетает"}, "correct": "a"}, {"n": 4, "question": "Какой роман русского писателя впервые широко прославил Бауыржана Момышулы?", "opts": {"a": "«Волоколамское шоссе» Александра Бека", "b": "«Война и мир» Толстого", "c": "Роман Пушкина", "d": "Роман Достоевского"}, "correct": "a"}, {"n": 5, "question": "Когда роман был впервые издан отдельной книгой?", "opts": {"a": "В 1978 году", "b": "В 2020 году", "c": "В 1900 году", "d": "Никогда не издавался"}, "correct": "a"}]}, {"grade": 8, "n": 29, "title": "Где нет зимы", "author": "Дина Сабитова", "questions": [{"n": 1, "question": "Как зовут главных героев повести — брата и сестру?", "opts": {"a": "Павел и Гуль", "b": "Иван и Мария", "c": "Алексей и Ольга", "d": "Дмитрий и Анна"}, "correct": "a"}, {"n": 2, "question": "С кем в основном живут дети в начале повести, пока мама ведёт вольный образ жизни?", "opts": {"a": "С бабушкой Шурой", "b": "С отцом", "c": "Одни, без взрослых", "d": "С дядей"}, "correct": "a"}, {"n": 3, "question": "Что происходит с бабушкой и мамой, из-за чего дети попадают в детский приют?", "opts": {"a": "Они умирают/исчезают", "b": "Они уезжают в отпуск", "c": "Ничего не происходит", "d": "Они переезжают вместе с детьми"}, "correct": "a"}, {"n": 4, "question": "Какое чувство ответственности испытывает старший брат Павел по отношению к сестре и дому?", "opts": {"a": "Никакого чувства ответственности", "b": "Уверенность, что пока стоит их Дом, они с сестрой не сироты", "c": "Полное безразличие", "d": "Желание избавиться от сестры"}, "correct": "b"}, {"n": 5, "question": "Какую главную ценность утверждает повесть?", "opts": {"a": "Что дом и семья дают человеку защиту и опору", "b": "Что деньги важнее всего", "c": "Что нужно жить в одиночестве", "d": "Что семья не имеет значения"}, "correct": "a"}]}, {"grade": 8, "n": 30, "title": "Чёрная звезда", "author": "Юрий Серебрянский", "questions": [{"n": 1, "question": "Роман-сказка «Чёрная звезда» написан в соавторстве с кем — чей это был первоначальный замысел?", "opts": {"a": "С Бахытжаном Момышулы (сыном Бауыржана Момышулы), передавшим рукопись отца", "b": "С зарубежным автором", "c": "Написан полностью в одиночку без чужой рукописи", "d": "С неизвестным автором"}, "correct": "a"}, {"n": 2, "question": "Как зовут главного героя — принца, отмеченного родинкой в форме чёрной звезды?", "opts": {"a": "Кара Жолдос", "b": "Гарри Поттер", "c": "Фродо", "d": "Аладдин"}, "correct": "a"}, {"n": 3, "question": "Кто воспитывает главного героя в детстве, помимо родителей?", "opts": {"a": "Волчица-кормилица и волк-защитник", "b": "Только слуги во дворце", "c": "Никто его не воспитывает", "d": "Только придворные учёные"}, "correct": "a"}, {"n": 4, "question": "Что делает главный герой, едва повзрослев?", "opts": {"a": "Покидает отчий дом в сопровождении спутников и путешествует между мирами", "b": "Остаётся во дворце навсегда", "c": "Уезжает учиться за границу в обычную школу", "d": "Ничего не делает"}, "correct": "a"}, {"n": 5, "question": "В каком жанре написано произведение?", "opts": {"a": "Роман-сказка", "b": "Строго научный труд", "c": "Детектив", "d": "Мемуары без вымысла"}, "correct": "a"}]}, {"grade": 9, "n": 1, "title": "Шырағың сөнбесін", "author": "Тахауи Ахтанов", "questions": [{"n": 1, "question": "Шығарма қандай кезеңдегі оқиғаларды бейнелейді?", "opts": {"a": "Кеңес одағына дейінгі көшпелі кезеңді", "b": "Ұлы Отан соғысы жылдарын", "c": "Тәуелсіздік алғаннан кейінгі жылдарды", "d": "Қазіргі заманғы қала өмірін"}, "correct": "b"}, {"n": 2, "question": "Шығарманың басты кейіпкері кім болып бейнеленеді?", "opts": {"a": "Теңізші", "b": "Дәрігер", "c": "Қала мұғалімі", "d": "Майданға аттанған қазақ жауынгері"}, "correct": "d"}, {"n": 3, "question": "Повестің атауындағы «шырақ» бейнесі не үшін қолданылған?", "opts": {"a": "Соғыстың аяқталуын білдіру үшін", "b": "Нақты жарық көзін сипаттау үшін", "c": "Үміт пен өмірдің үзілмеуін білдіру үшін", "d": "Мереке салтанатын көрсету үшін"}, "correct": "c"}, {"n": 4, "question": "Шығармада отбасы мен майдандағы жақынның арасын не байланыстырып тұрады?", "opts": {"a": "Телефон қоңыраулары", "b": "Бірге өткізілген сапар", "c": "Ортақ кәсіп", "d": "Хаттар мен күту сезімі"}, "correct": "d"}, {"n": 5, "question": "Шығарманың жалпы көңіл-күйі қандай сипатта берілген?", "opts": {"a": "Күлкілі және жеңіл", "b": "Қорқынышты, триллер сарынды", "c": "Мұңды, бірақ үмітті", "d": "Салтанатты және мерекелік"}, "correct": "c"}]}, {"grade": 9, "n": 2, "title": "Ұшқан ұя", "author": "Бауыржан Момышұлы", "questions": [{"n": 1, "question": "«Ұшқан ұя» атауы негізінен нені білдіреді?", "opts": {"a": "Соғыстағы бір шайқас атауын", "b": "Автордың туған ауылы мен балалық шағын", "c": "Жаңа қоныс аударылған қаланы", "d": "Құс шаруашылығы жайлы кітап екенін"}, "correct": "b"}, {"n": 2, "question": "Шығарма қай жанрда жазылған?", "opts": {"a": "Естелік-мемуарлық повесть", "b": "Детектив", "c": "Ғылыми фантастика", "d": "Комедия пьесасы"}, "correct": "a"}, {"n": 3, "question": "Автор шығармада негізінен неге баса назар аударады?", "opts": {"a": "Ұрпақтан-ұрпаққа берілетін тәрбие мен қазақи құндылықтарға", "b": "Спорттық жарыстарға", "c": "Ғарышты игеруге", "d": "Қалалық индустрияның дамуына"}, "correct": "a"}, {"n": 4, "question": "Шығармадағы бала кезіндегі оқиғалар негізінен қандай ортада өтеді?", "opts": {"a": "Үлкен мегаполисте", "b": "Шетелдік университетте", "c": "Ауыл және дала өмірінде", "d": "Теңіз жағалауында"}, "correct": "c"}, {"n": 5, "question": "Автордың балалық шағын суреттеуінің басты мақсаты неде?", "opts": {"a": "Тарихи оқулық жазу", "b": "Географиялық сипаттама беру", "c": "Адамның қалыптасуына отбасы мен ортаның әсерін көрсету", "d": "Тек қызықты оқиға баяндау"}, "correct": "c"}]}, {"grade": 9, "n": 3, "title": "Дайағашшы", "author": "Ұларбек Нұрғалымұлы", "questions": [{"n": 1, "question": "Шығарманың атауы қандай кәсіппен байланысты?", "opts": {"a": "Теңізшілікпен", "b": "Мұғалімдікпен", "c": "Дәрігерлікпен", "d": "Дайағаш (тіреу/қада) орнатумен айналысатын кәсіппен"}, "correct": "d"}, {"n": 2, "question": "Шығарма негізінен қай ортадағы адамдардың өмірін бейнелейді?", "opts": {"a": "Қарапайым еңбек адамдарының", "b": "Ғалымдардың", "c": "Ел басқарушылардың", "d": "Артистердің"}, "correct": "a"}, {"n": 3, "question": "Шығармадағы басты кейіпкердің ісіне қоғам қалай қарайды?", "opts": {"a": "Ешкім байқамайды, себебі жасырын жұмыс", "b": "Оның еңбегі бағаланбай, елеусіз қалады", "c": "Кейіпкер жұмысынан бас тартады", "d": "Бірден марапатталады"}, "correct": "b"}, {"n": 4, "question": "Шығарманың негізгі идеясы неге саяды?", "opts": {"a": "Байлықтың бақыт әкелетініне", "b": "Қалаға көшудің пайдасына", "c": "Қарапайым еңбектің де қоғам үшін маңызды екеніне", "d": "Ғылымның өнерден жоғары екеніне"}, "correct": "c"}, {"n": 5, "question": "Шығарма қандай стильде жазылған?", "opts": {"a": "Өлең-жыр түрінде", "b": "Ертегі-аңыз түрінде", "c": "Реалистік, өмірлік баяндау стилінде", "d": "Мистикалық хикая түрінде"}, "correct": "c"}]}, {"grade": 9, "n": 4, "title": "Дермене", "author": "Дулат Исабеков", "questions": [{"n": 1, "question": "Дулат Исабеков негізінен қандай жанрда танымал жазушы?", "opts": {"a": "Тарихи оқулықтармен", "b": "Ғылыми-көпшілік кітаптарымен", "c": "Балаларға арналған ертегілерімен", "d": "Психологиялық драма мен повестерімен"}, "correct": "d"}, {"n": 2, "question": "«Дермене» шығармасында автор көбіне неге назар аударады?", "opts": {"a": "Кейіпкердің ішкі жан дүниесі мен адамгершілік таңдауына", "b": "Ғарыштық оқиғаларға", "c": "Экономикалық дағдарысқа", "d": "Спорттық жеңіске"}, "correct": "a"}, {"n": 3, "question": "Шығарманың оқиғасы негізінен қай ортада өтеді?", "opts": {"a": "Мұхит үстінде", "b": "Ғарыш кемесінде", "c": "Шетелдік қалада", "d": "Қазақ ауылында"}, "correct": "d"}, {"n": 4, "question": "Автордың шығармаларына тән басты ерекшелік не?", "opts": {"a": "Кейіпкер тағдыры арқылы моральдық мәселе көтеру", "b": "Тарихи құжаттарға сүйену", "c": "Қатаң ғылыми дәлдік", "d": "Күлкілі оқиғалар тізбегі"}, "correct": "a"}, {"n": 5, "question": "Шығарманың негізгі тартысы неге негізделген?", "opts": {"a": "Ғылыми жаңалық ашуға", "b": "Екі мемлекеттің соғысына", "c": "Спорттық жарысқа", "d": "Кейіпкердің ар-ождан мен жағдай арасындағы тайталасына"}, "correct": "d"}]}, {"grade": 9, "n": 5, "title": "Аяқ киім сатушы", "author": "Фил Найт", "questions": [{"n": 1, "question": "Кітаптың авторы қай әлемге әйгілі брендтің негізін қалаушы?", "opts": {"a": "Nike компаниясының", "b": "Adidas компаниясының", "c": "Apple компаниясының", "d": "Coca-Cola компаниясының"}, "correct": "a"}, {"n": 2, "question": "Автор бизнесін бастағанда алғаш қай елдің аяқ киімін сатумен айналысты?", "opts": {"a": "Оңтүстік Кореяның", "b": "Жапонияның (Onitsuka Tiger)", "c": "Қытайдың", "d": "Германияның"}, "correct": "b"}, {"n": 3, "question": "Кітапта компания қандай атаумен танымал болғанға дейін «Blue Ribbon Sports» деп аталды ма?", "opts": {"a": "Жоқ, «Adidas Kids» деп аталды", "b": "Иә, алғашқы атауы «Blue Ribbon Sports» болды", "c": "Жоқ, бастапқыда «Nike» деп аталды", "d": "Иә, бірақ кейін «Puma» болды"}, "correct": "b"}, {"n": 4, "question": "Кітапта автордың бизнесі дамуында ең үлкен қиындық ретінде не сипатталады?", "opts": {"a": "Ақша қаражатының тапшылығы мен банктермен қарым-қатынас", "b": "Заңды тыйым салулар", "c": "Жарнама болмауы", "d": "Қызметкерлердің жетіспеуі"}, "correct": "a"}, {"n": 5, "question": "Кітаптың басты идеясы неге саяды?", "opts": {"a": "Спорттың денсаулыққа пайдасына", "b": "Жапон мәдениетінің тарихына", "c": "Ойлап тапқан адам бірден бай болатынына", "d": "Табандылық пен тәуекелге бару арқылы үлкен нәтижеге жетуге болатынына"}, "correct": "d"}]}, {"grade": 9, "n": 6, "title": "Біз үшеу едік", "author": "Төлен Әбдік", "questions": [{"n": 1, "question": "Шығарманың атауынан не аңғаруға болады?", "opts": {"a": "Оқиға үш жақын адамның (достың) тағдыры туралы екенін", "b": "Үш мемлекет туралы екенін", "c": "Үш ғылыми жаңалық туралы екенін", "d": "Үш жыл мерзімі туралы екенін"}, "correct": "a"}, {"n": 2, "question": "Төлен Әбдіктің прозасына тән негізгі белгі не?", "opts": {"a": "Тек өлең түрінде жазу", "b": "Кейіпкердің ішкі психологиясын терең ашу", "c": "Ғылыми-фантастикалық сюжет құру", "d": "Тек тарихи деректерге сүйену"}, "correct": "b"}, {"n": 3, "question": "Шығармадағы достықтың сыны неден көрінеді?", "opts": {"a": "Өмірдегі қиын сәттерде адамдардың шынайы бет-бейнесі ашылуынан", "b": "Достардың бірге саяхатқа шығуынан", "c": "Достардың бірге спорт ойнауынан", "d": "Достардың ортақ бизнес құруынан"}, "correct": "a"}, {"n": 4, "question": "Шығарма қандай баяндау формасында жазылған деп есептеледі?", "opts": {"a": "Бірінші жақтан, естелік-ойталқы түрінде", "b": "Ресми есеп түрінде", "c": "Ертегілік аңыз түрінде", "d": "Драмалық диалог түрінде"}, "correct": "a"}, {"n": 5, "question": "Шығарманың негізгі идеясы неге саяды?", "opts": {"a": "Ғылыми жаңалық ашуға", "b": "Адамдық қарым-қатынас пен адалдықтың сыналуына", "c": "Байлыққа жетудің жолына", "d": "Спорттық жеңіске жетуге"}, "correct": "b"}]}, {"grade": 9, "n": 7, "title": "Сақиналар әміршісі: сақина бауырластығы", "author": "Джон Рональд Руэл Толкин", "questions": [{"n": 1, "question": "Хикаяның басты кейіпкері кім, оған қатерлі сақина мұраға қалады?", "opts": {"a": "Гэндальф", "b": "Боромир", "c": "Фродо Бэггинс", "d": "Арагорн"}, "correct": "c"}, {"n": 2, "question": "Сақинаны жою үшін оны қай тауға апару керек?", "opts": {"a": "Ерекше мұзды тау", "b": "Ол ешқандай тауға апарылмайды", "c": "Елфтер тауы", "d": "Оқмантау (Mount Doom)"}, "correct": "d"}, {"n": 3, "question": "Фродоға сақинаны алғаш сыйлаған, оны бала кезінен тәрбиелеген кейіпкер кім?", "opts": {"a": "Бильбо Бэггинс", "b": "Гэндальф", "c": "Элронд", "d": "Сэм Гэмджи"}, "correct": "a"}, {"n": 4, "question": "Сақина бауырластығы (Fellowship) неше мүшеден құралады?", "opts": {"a": "Он екі", "b": "Тоғыз", "c": "Бес", "d": "Үш"}, "correct": "b"}, {"n": 5, "question": "Кітаптың соңында бауырластықты ішінара бөлшектейтін оқиға не болады?", "opts": {"a": "Гэндальфтың патша болуы", "b": "Боромирдің сақинаны тартып алуға әрекеттенуі және оның қайтыс болуы", "c": "Фродоның үйге қайтуы", "d": "Сақинаны жою рәсімі"}, "correct": "b"}]}, {"grade": 9, "n": 8, "title": "Шешендік өнер", "author": "Дейл Карнеги", "questions": [{"n": 1, "question": "Кітаптың негізгі тақырыбы не?", "opts": {"a": "Спорттық жаттығулар", "b": "Ғылыми зерттеу әдістері", "c": "Көпшілік алдында сөйлеу шеберлігі мен өзіне сенімділік", "d": "Тарихи оқиғалар"}, "correct": "c"}, {"n": 2, "question": "Автордың пікірінше, сөз сөйлеу қорқынышын жеңудің басты жолы қандай?", "opts": {"a": "Сахнаға шықпау", "b": "Сөзді толық жаттап алу", "c": "Тыңдармандардан қашу", "d": "Жаттығу мен тәжірибе жинақтау"}, "correct": "d"}, {"n": 3, "question": "Кітап негізінен қандай жанрға жатады?", "opts": {"a": "Өзін-өзі дамыту (нон-фикшн)", "b": "Роман", "c": "Тарихи хроника", "d": "Ғылыми-фантастика"}, "correct": "a"}, {"n": 4, "question": "Автор жақсы шешеннің басты қасиеті ретінде нені атайды?", "opts": {"a": "Дауыстың қаттылығын", "b": "Күрделі сөздер қолдануды", "c": "Ұзақ сөйлеуді", "d": "Тыңдарманмен байланыс орнату қабілетін"}, "correct": "d"}, {"n": 5, "question": "Кітапта сөз сөйлеуге дайындықтың қандай маңызы аталады?", "opts": {"a": "Мұқият дайындық сенімділікті арттырады", "b": "Тек жазбаша мәтін жеткілікті", "c": "Дайындықтың қажеті жоқ", "d": "Тек тумысынан шешен адамдарға ғана қажет"}, "correct": "a"}]}, {"grade": 9, "n": 9, "title": "Ақ кеме", "author": "Шыңғыс Айтматов", "questions": [{"n": 1, "question": "Шығармадағы бала неге айналуды армандайды?", "opts": {"a": "Патшаға айналуға", "b": "Батырға айналуға", "c": "Балыққа айналып, әкесін іздеп кетуге", "d": "Құсқа айналып ұшуға"}, "correct": "c"}, {"n": 2, "question": "Баланың атасы Момын оған қандай аңыз әңгімелейді?", "opts": {"a": "Жеті қарақшы туралы аңызды", "b": "Алтын құс туралы аңызды", "c": "Мүйізді Ана-Бұғы туралы аңызды", "d": "Ұшқан кілем туралы аңызды"}, "correct": "c"}, {"n": 3, "question": "Шығармадағы теріс кейіпкер, ана-бұғы аңызын аяққа таптайтын кім?", "opts": {"a": "Гүлжамал", "b": "Орозқұл", "c": "Сейдахмет", "d": "Момын"}, "correct": "b"}, {"n": 4, "question": "Шығарманың соңында бала бастан не кешіреді?", "opts": {"a": "Атасымен бірге қалаға көшеді", "b": "Балыққа айналам деп өзеннен ағып кетеді (қайғылы аяқталады)", "c": "Мектепті бітіріп, инженер болады", "d": "Достарымен жеңіске жетеді"}, "correct": "b"}, {"n": 5, "question": "«Ақ кеме» шығармасының басты идеясы неге саяды?", "opts": {"a": "Балалық арман мен қатал шындықтың қақтығысына", "b": "Теңіз саяхатының қызығына", "c": "Спорттық жарысқа", "d": "Соғыс тарихына"}, "correct": "a"}]}, {"grade": 9, "n": 10, "title": "Алхимик", "author": "Пауло Коэльо", "questions": [{"n": 1, "question": "Романның бас кейіпкері кім?", "opts": {"a": "Ағылшын ғалымы", "b": "Африкалық сахарашы", "c": "Испаниялық қой баққан жас жігіт Сантьяго", "d": "Мысырлық сатушы"}, "correct": "c"}, {"n": 2, "question": "Сантьягоны сапарға түртетін негізгі себеп не?", "opts": {"a": "Соғыстан қашу", "b": "Отбасының қуып жіберуі", "c": "Пирамидалар маңында қазына бар туралы қайталанған түс", "d": "Университетке оқуға түсу"}, "correct": "c"}, {"n": 3, "question": "Сантьяго сахарада ғашық болатын әйелдің есімі кім?", "opts": {"a": "Роза", "b": "Айгүл", "c": "Фатима", "d": "Мария"}, "correct": "c"}, {"n": 4, "question": "Роман бойынша «Жеке аңыз» (Personal Legend) деген не?", "opts": {"a": "Әр адамның орындауға тағдырлы өз арманы", "b": "Ежелгі мысырлық миф", "c": "Алхимиктің құпия рецепті", "d": "Сахарадағы керуен жолы"}, "correct": "a"}, {"n": 5, "question": "Роман соңында қазына нақты қай жерден табылады?", "opts": {"a": "Сантьяго сапарын бастаған шіркеу маңынан", "b":