orrect": "c"}, {"n": 4, "question": "Шығарма қандай стильде жазылған?", "opts": {"a": "Құрғақ ғылыми талдау", "b": "Ресми құжат түрі", "c": "Лирикалық-психологиялық баяндау", "d": "Күлкілі анекдот"}, "correct": "c"}, {"n": 5, "question": "Автор шығармада уақыт өткен сайын не өзгереді дейді?", "opts": {"a": "Ештеңе өзгермейді", "b": "Сыртқы өмір өзгергенімен, ішкі бала бейнесі сақталады", "c": "Тек сыртқы келбет қана маңызды", "d": "Бала бейнесі толығымен жоғалады"}, "correct": "b"}]}, {"grade": 10, "n": 3, "title": "Волоколамск тас жолы", "author": "Александр Бек", "questions": [{"n": 1, "question": "Шығарма қай тарихи оқиғаға негізделген?", "opts": {"a": "Азамат соғысына", "b": "1941 жылы Мәскеу түбіндегі қорғаныс шайқастарына", "c": "Ауғанстан соғысына", "d": "Ұлы Жеңіс тойына"}, "correct": "b"}, {"n": 2, "question": "Шығармада қай нақты қолбасшының тағылымы негізге алынған?", "opts": {"a": "Бауыржан Момышұлының", "b": "Панфиловтың жеке өмірбаяны", "c": "Жуковтың", "d": "Сталиннің"}, "correct": "a"}, {"n": 3, "question": "Шығарма қандай баяндау түрінде жазылған?", "opts": {"a": "Ғылыми фантастика", "b": "Күнделік-әзіл жазба", "c": "Құжаттық-көркем повесть (шайқас тактикасын баяндайтын)", "d": "Ертегі-аңыз"}, "correct": "c"}, {"n": 4, "question": "Шығармада баса көрсетілетін әскери тактика не?", "opts": {"a": "Кездейсоқ шабуыл", "b": "Тек қорғанбай тұру", "c": "Ұйымдасқан ұрыс тәртібі мен шегіну кезіндегі тәртіп сақтау", "d": "Дереу қашу"}, "correct": "c"}, {"n": 5, "question": "Шығарманың атауындағы жол қай қаланы қорғауда маңызды болды?", "opts": {"a": "Ленинградты", "b": "Сталинградты", "c": "Мәскеуді", "d": "Алматыны"}, "correct": "c"}]}, {"grade": 10, "n": 4, "title": "Ұшқан ұя", "author": "Бауыржан Момышұлы", "questions": [{"n": 1, "question": "«Ұшқан ұя» шығармасы негізінен нені баяндайды?", "opts": {"a": "Ғарышты игеруді", "b": "Қазіргі заманғы қала өмірін", "c": "Соғыс жылдарындағы шайқастарды", "d": "Автордың балалық шағы мен қалыптасуын"}, "correct": "d"}, {"n": 2, "question": "Шығарма қандай жанрда жазылған?", "opts": {"a": "Естелік-мемуарлық повесть", "b": "Өлеңдер жинағы", "c": "Роман-эпопея", "d": "Пьеса"}, "correct": "a"}, {"n": 3, "question": "Автор шығармада қазақи тәрбиенің қандай тұстарын көрсетеді?", "opts": {"a": "Тек тағамдық дәстүрлерді", "b": "Тек киім үлгілерін", "c": "Тек мал бағу тәсілдерін", "d": "Үлкенге құрмет, еңбекқорлық, ұждан тазалығы"}, "correct": "d"}, {"n": 4, "question": "Шығарманың басты идеясы неге саяды?", "opts": {"a": "Байлықтың бақыт әкелетініне", "b": "Соғыстың мәнсіздігіне", "c": "Адамның қалыптасуына тегі мен ортаның берік іргетас болатынына", "d": "Қалаға көшудің қажеттігіне"}, "correct": "c"}, {"n": 5, "question": "Атаудағы «ұя» сөзі негізінен нені білдіреді?", "opts": {"a": "Әскери бекіністі", "b": "Нақты құс ұясын", "c": "Мектеп ғимаратын", "d": "Адамның тамыры мен туған ортасын"}, "correct": "d"}]}, {"grade": 10, "n": 5, "title": "Хачико", "author": "Луис Пратс", "questions": [{"n": 1, "question": "Хачико қай елде болған оқиғаға негізделген?", "opts": {"a": "Ресейде", "b": "Испанияда", "c": "Қазақстанда", "d": "Жапонияда"}, "correct": "d"}, {"n": 2, "question": "Хачико күн сайын иесін қай жерде күтетін?", "opts": {"a": "Теміржол вокзалында", "b": "Үйде", "c": "Университетте", "d": "Саябақта"}, "correct": "a"}, {"n": 3, "question": "Профессор (иесі) жұмыс орнында не болады?", "opts": {"a": "Шетелге көшеді", "b": "Ауырып, ауруханада қалады", "c": "Зейнетке шығады", "d": "Кенеттен қайтыс болады"}, "correct": "d"}, {"n": 4, "question": "Иесінен кейін Хачико қанша жылдай оны күтуді жалғастырады?", "opts": {"a": "Он жыл", "b": "Бір апта", "c": "Тоғыз жылдан астам", "d": "Бір ай"}, "correct": "c"}, {"n": 5, "question": "Хачиконың адалдығы кейін немен мәңгі есте қалды?", "opts": {"a": "Ол мұражайға қойылды", "b": "Оның суреті теледидарда көрсетілді", "c": "Оның есімімен көше аталды", "d": "Вокзал маңында оның құрметіне мүсін орнатылды"}, "correct": "d"}]}, {"grade": 10, "n": 6, "title": "Жар жағалаған жалғыз", "author": "Сэлinджер Джером", "questions": [{"n": 1, "question": "Романның бас кейіпкері қандай жастағы жасөспірім?", "opts": {"a": "Мектептен шығарылған жасөспірім жігіт", "b": "Кіші мектеп оқушысы", "c": "Ересек әйел", "d": "Қарт ер адам"}, "correct": "a"}, {"n": 2, "question": "Кейіпкер оқиға барысында негізінен қайда жүреді?", "opts": {"a": "Соғысқа аттанады", "b": "Мектептен қуылып, Нью-Йорк қаласында сандалып жүреді", "c": "Ғарышқа ұшады", "d": "Ауылда мал бағады"}, "correct": "b"}, {"n": 3, "question": "Кейіпкердің ересектер әлеміне деген көзқарасы қандай?", "opts": {"a": "Мүлдем немқұрайлы", "b": "Жалған, екіжүзді деп сынайды", "c": "Толықтай сүйсінеді", "d": "Оны түсінбейді"}, "correct": "b"}, {"n": 4, "question": "Кейіпкердің атауға негіз болған «жар жағалаған» бейнесі неге меңзейді?", "opts": {"a": "Балаларды қауіптен сақтап қалу арманына", "b": "Аңшылыққа", "c": "Ғимарат салуға", "d": "Теңізде жүзуге"}, "correct": "a"}, {"n": 5, "question": "Роман қандай баяндау формасында жазылған?", "opts": {"a": "Үшінші жақтан, тарихи құжат түрінде", "b": "Хаттар жинағы түрінде", "c": "Бірінші жақтан, кейіпкердің өз тілімен әңгімеленеді", "d": "Өлең түрінде"}, "correct": "c"}]}, {"grade": 10, "n": 7, "title": "Жасампаз жандардың 7 дағдысы", "author": "Стивен Кови", "questions": [{"n": 1, "question": "Кітаптағы бірінші дағды қалай аталады?", "opts": {"a": "Белсенді болу (Проактивті болу)", "b": "Жеңіс-жеңіс ойлау", "c": "Алдымен түсінуге тырысу", "d": "Синергияға жету"}, "correct": "a"}, {"n": 2, "question": "Кітапта аяқталуды ойда ұстап бастау қандай дағды деп аталады?", "opts": {"a": "Ынтымақтастық", "b": "Мақсатты алдын ала белгілеп бастау", "c": "Тыңдай білу", "d": "Кезек күту"}, "correct": "b"}, {"n": 3, "question": "«Жеңіс-жеңіс» (Win-Win) принципі нені білдіреді?", "opts": {"a": "Екі жақтың да мүддесін ескеретін шешім табу", "b": "Бәрінен бас тарту", "c": "Тек өз пайдаңды ойлау", "d": "Бәсекелестен жеңіп алу"}, "correct": "a"}, {"n": 4, "question": "Кітап бойынша тиімді қарым-қатынастың кілті не?", "opts": {"a": "Алдымен түсінуге тырысып, содан кейін түсінікті болу", "b": "Үнсіз қалу", "c": "Дауыс көтеру", "d": "Тек өз пікірін айту"}, "correct": "a"}, {"n": 5, "question": "Соңғы, жетінші дағды неге арналған?", "opts": {"a": "Демалысқа шығу", "b": "Өзін-өзі жаңарту (арені шыңдау)", "c": "Ақшаны үнемдеу", "d": "Спортпен айналысу"}, "correct": "b"}]}, {"grade": 10, "n": 8, "title": "Ай мен Айша", "author": "Шерхан Мұртаза", "questions": [{"n": 1, "question": "Шығарманың атауындағы «Ай» мен «Айша» негізінен нені білдіреді?", "opts": {"a": "Нақты екі қаланың атауын", "b": "Символдық-лирикалық бейнелерді (сүйіспеншілік пен тағдыр)", "c": "Ғылыми терминдерді", "d": "Екі мемлекеттің атауын"}, "correct": "b"}, {"n": 2, "question": "Шерхан Мұртаза шығармаларына тән негізгі стиль қандай?", "opts": {"a": "Құрғақ ғылыми баяндау", "b": "Ресми есеп беру стилі", "c": "Тек күлкілі диалогтар", "d": "Лирикалық-философиялық, терең әлеуметтік мәселелерді көтеру"}, "correct": "d"}, {"n": 3, "question": "Шығармада көтерілетін басты тақырып не?", "opts": {"a": "Сүйіспеншілік пен адамгершілік таңдау", "b": "Мал шаруашылығы", "c": "Спорттық жарыстар", "d": "Ғарышты игеру"}, "correct": "a"}, {"n": 4, "question": "Шығарманың соңы қандай сипатта болады?", "opts": {"a": "Мүлдем шешілмеген ашық финал", "b": "Ғылыми қорытынды", "c": "Күлкілі хэппи-энд", "d": "Драмалық, ойлануға негізделген аяқталу"}, "correct": "d"}, {"n": 5, "question": "Автор шығарма арқылы оқырманды неге шақырады?", "opts": {"a": "Экономикалық есеп жүргізуге", "b": "Адамгершілік пен ар-ождан туралы ойлануға", "c": "Тек көңіл көтеруге", "d": "Тарихи деректерді жаттауға"}, "correct": "b"}]}, {"grade": 10, "n": 9, "title": "Икигай", "author": "Кен Моги", "questions": [{"n": 1, "question": "«Икигай» сөзі қай тілден алынған және нені білдіреді?", "opts": {"a": "Корей тілінен, «табыс» дегенді білдіреді", "b": "Қытай тілінен, «денсаулық» дегенді білдіреді", "c": "Жапон тілінен, «өмір сүру мәні/себебі» дегенді білдіреді", "d": "Ағылшын тілінен, «бақыт» дегенді білдіреді"}, "correct": "c"}, {"n": 2, "question": "Автордың пікірінше, икигай табу үшін не маңызды?", "opts": {"a": "Кішкентай нәрселерден қуаныш табу және қазіргі сәтке назар аудару", "b": "Тек көп ақша табу", "c": "Тек атақ-даңққа ұмтылу", "d": "Басқалармен бәсекелесу"}, "correct": "a"}, {"n": 3, "question": "Кітапта икигайдың қай саладан ғана емес екені түсіндіріледі?", "opts": {"a": "Тек жоғары мансап пен табыстан ғана емес, кез келген қарапайым іс-әрекеттен де табылатыны", "b": "Тек спорттан ғана табылатыны", "c": "Тек саяхаттан ғана табылатыны", "d": "Тек ғылымнан ғана табылатыны"}, "correct": "a"}, {"n": 4, "question": "Кітап негізінен қандай жанрға жатады?", "opts": {"a": "Тарихи хроника", "b": "Ғылыми-фантастика", "c": "Роман", "d": "Өзін-өзі дамыту / жапон философиясы туралы нон-фикшн"}, "correct": "d"}, {"n": 5, "question": "Автор «шеберлікке ұмтылу» тұжырымдамасын қандай мысалмен түсіндіреді?", "opts": {"a": "Жапондық қолөнершілер мен аспазшылардың өз ісіне берілгендігімен", "b": "Ғарышкерлердің ұшуымен", "c": "Спортшылардың жарыс жеңісімен", "d": "Саясаткерлердің сөйлеген сөзімен"}, "correct": "a"}]}, {"grade": 10, "n": 10, "title": "Кербұғы", "author": "Оралхан Бөкей", "questions": [{"n": 1, "question": "«Кербұғы» атауындағы «бұғы» деген не?", "opts": {"a": "Құс атауы", "b": "Балық түрі", "c": "Асқақ, сұлу мүйізді жабайы аң", "d": "Үй жануары"}, "correct": "c"}, {"n": 2, "question": "Оралхан Бөкей прозасына тән негізгі тақырып не?", "opts": {"a": "Саяси күрес", "b": "Қалалық индустрия", "c": "Адам мен табиғаттың арақатынасы", "d": "Ғылыми жаңалықтар"}, "correct": "c"}, {"n": 3, "question": "Шығармада аңшылық қалай бейнеленеді?", "opts": {"a": "Тек экономикалық пайда ретінде көрсетіледі", "b": "Адамгершілік пен ар-ождан тұрғысынан сыналады", "c": "Мүлдем айтылмайды", "d": "Тек қызық ойын ретінде мадақталады"}, "correct": "b"}, {"n": 4, "question": "Автордың табиғат бейнесі шығармаларында қандай рөл атқарады?", "opts": {"a": "Тек көрікті фон ретінде", "b": "Тірі, жанды күш ретінде, адаммен тең дәрежеде", "c": "Мүлдем суреттелмейді", "d": "Тек ғылыми деректер түрінде"}, "correct": "b"}, {"n": 5, "question": "Шығарманың негізгі идеясы неге саяды?", "opts": {"a": "Табиғатқа қиянат жасаудың адамгершілікке жат екеніне", "b": "Қала өмірінің артықшылығына", "c": "Ғылыми прогреске", "d": "Аңшылықтың пайдалы кәсіп екеніне"}, "correct": "a"}]}, {"grade": 10, "n": 11, "title": "Дарабоз", "author": "Қабдеш Жұмаділов", "questions": [{"n": 1, "question": "«Дарабоз» романы қай тарихи кезеңге негізделген?", "opts": {"a": "Тәуелсіздік алғаннан кейінгі жылдарға", "b": "Кеңес одағы кезеңіне", "c": "Қазіргі заманға", "d": "Қазақ-жоңғар соғыстары дәуіріне"}, "correct": "d"}, {"n": 2, "question": "Роман кімнің батырлық жолын арқау етеді?", "opts": {"a": "Абайдың", "b": "Абылай ханның жалғыз өзінің", "c": "Қабанбай батырдың", "d": "Кенесары ханның"}, "correct": "c"}, {"n": 3, "question": "Романда негізінен қандай тақырып көтеріледі?", "opts": {"a": "Сауда-саттық мәселелері", "b": "Отбасылық драма ғана", "c": "Ғылыми жаңалықтар", "d": "Ел бірлігі мен жаудан қорғану қажеттігі"}, "correct": "d"}, {"n": 4, "question": "Роман қандай жанрда жазылған?", "opts": {"a": "Тарихи роман", "b": "Ғылыми фантастика", "c": "Комедия", "d": "Күнделік жазба"}, "correct": "a"}, {"n": 5, "question": "Автор батыр бейнесін қалай көрсетеді?", "opts": {"a": "Ел бірлігі үшін жан аямаған қайраткер ретінде", "b": "Қорқақ адам ретінде", "c": "Билікке құмар адам ретінде", "d": "Тек жеке даңқ іздеген адам ретінде"}, "correct": "a"}]}, {"grade": 10, "n": 12, "title": "Ақ боз үй", "author": "Смағұл Елубай", "questions": [{"n": 1, "question": "Роман қай тарихи қасіретті бейнелейді?", "opts": {"a": "Кеңес одағының құлауын", "b": "Ұлы Отан соғысын", "c": "Тәуелсіздік жылдарын", "d": "1930 жылдардағы ашаршылықты"}, "correct": "d"}, {"n": 2, "question": "Романның атауындағы «ақ боз үй» немен байланысты?", "opts": {"a": "Қалалық үймен", "b": "Аурухана ғимаратымен", "c": "Қазақ отбасының дәстүрлі мекен-жайы — киіз үймен", "d": "Мектеп ғимаратымен"}, "correct": "c"}, {"n": 3, "question": "Роман негізінен нені бейнелейді?", "opts": {"a": "Соғыстағы жеңісті", "b": "Ғылыми жетістікті", "c": "Той-думанды", "d": "Ашаршылық жылдарындағы қазақ отбасының ауыр тағдырын"}, "correct": "d"}, {"n": 4, "question": "Автор шығармада көбіне қандай сезімге басымдық береді?", "opts": {"a": "Аштық пен қайғы-мұң, бірақ өмірге деген үміт", "b": "Тек қуаныш пен той", "c": "Әзіл-қалжың", "d": "Тек ғылыми талдау"}, "correct": "a"}, {"n": 5, "question": "Роман қазақ халқы үшін қандай мәнге ие деп саналады?", "opts": {"a": "Тек ойын-сауық ретінде", "b": "Тек георафиялық сипаттама ретінде", "c": "Тек тілді үйрену құралы ретінде", "d": "Ұлттық қасіретті есте сақтау мен тарихи шындықты айту"}, "correct": "d"}]}, {"grade": 10, "n": 13, "title": "Алтын Орда", "author": "Ілияс Есенберлин", "questions": [{"n": 1, "question": "«Алтын Орда» романы қай тарихи мемлекетке арналған?", "opts": {"a": "Моңғол-қыпшақ дәуіріндегі Алтын Орда мемлекетіне", "b": "Ресей патшалығына", "c": "Осман империясына", "d": "Қытай империясына"}, "correct": "a"}, {"n": 2, "question": "Роман кімнің трилогиясының бір бөлігі болып саналады?", "opts": {"a": "Жеке дара шығарма, трилогияға кірмейді", "b": "«Қан мен тер» романының", "c": "«Көшпенділер» трилогиясының", "d": "«Абай жолы» роман-эпопеясының"}, "correct": "c"}, {"n": 3, "question": "Роман негізінен нені бейнелейді?", "opts": {"a": "Ғылыми жаңалықтарды", "b": "Қалалық қазіргі заман өмірін", "c": "Хандар мен билік үшін күрес, мемлекеттің құрылуы мен ыдырауын", "d": "Жеке отбасылық драманы ғана"}, "correct": "c"}, {"n": 4, "question": "Роман қандай жанрда жазылған?", "opts": {"a": "Тарихи роман", "b": "Күнделік", "c": "Лирикалық поэма", "d": "Ғылыми фантастика"}, "correct": "a"}, {"n": 5, "question": "Автор тарихи оқиғаларды баяндағанда неге басымдық береді?", "opts": {"a": "Жеке қаһармандардың ойын-сауығына", "b": "Ауа-райы жағдайына", "c": "Сауда жолдарының картасына", "d": "Ел бірлігі мен мемлекеттіліктің маңызына"}, "correct": "d"}]}, {"grade": 10, "n": 14, "title": "Сақиналар әміршісі: сақина бауырластығы", "author": "Джон Рональд Руэл Толкин", "questions": [{"n": 1, "question": "Хикаяның басты кейіпкері Фродо қай халыққа (нәсілге) жатады?", "opts": {"a": "Гном", "b": "Хоббит", "c": "Эльф", "d": "Адам"}, "correct": "b"}, {"n": 2, "question": "Сақина туралы шешім қабылданатын үлкен кеңес қай жерде өтеді?", "opts": {"a": "Шайрда", "b": "Ривенделлде (Элрондтың үйінде)", "c": "Гондорда", "d": "Мордорда"}, "correct": "b"}, {"n": 3, "question": "Бауырластыққа қосылған, бірақ сақинаны тартып алуға әрекеттенген адам кім?", "opts": {"a": "Леголас", "b": "Арагорн", "c": "Боромир", "d": "Гимли"}, "correct": "c"}, {"n": 4, "question": "Гэндальф кітаптың бірінші кітабының соңында не болады?", "opts": {"a": "Шайрға оралады", "b": "Сақинаны жояды", "c": "Мория үңгірінде балрогпен күресіп, құлап кетеді", "d": "Патша болып тағайындалады"}, "correct": "c"}, {"n": 5, "question": "Сақина ешкімге зиян бермей жойылатын жалғыз орын қай жерде?", "opts": {"a": "Ривенделл", "b": "Оқмантаудың лаваы (Мордордағы)", "c": "Шайр", "d": "巴 Роханның даласы"}, "correct": "b"}]}, {"grade": 10, "n": 15, "title": "Он бес жасар капитан", "author": "Жюль Верн", "questions": [{"n": 1, "question": "Романның бас кейіпкері Дик Санд неше жасында кеменің капитаны болуға мәжбүр болады?", "opts": {"a": "Он сегіз жасында", "b": "Он бес жасында", "c": "Он жасында", "d": "Жиырма жасында"}, "correct": "b"}, {"n": 2, "question": "Кеменің бұрынғы капитаны Гуль немен қайтыс болады?", "opts": {"a": "Соғыста", "b": "Аурудан", "c": "Дауылда", "d": "Кит аулау кезіндегі жазатайым оқиғада"}, "correct": "d"}, {"n": 3, "question": "Кеменің бағытын қасақана бұрмалап, оқиғаны шиеленістіретін теріс кейіпкер кім?", "opts": {"a": "Джек", "b": "Геркулес", "c": "Негоро (аспазшы)", "d": "Уэлдон ханым"}, "correct": "c"}, {"n": 4, "question": "Кеме, Американың орнына кездейсоқ қай құрлыққа жетіп қалады?", "opts": {"a": "Азияға", "b": "Австралияға", "c": "Антарктидаға", "d": "Африкаға"}, "correct": "d"}, {"n": 5, "question": "Дик Сандқа қиын сәттерде көмектесетін, бұрын құл болған мықты кейіпкер кім?", "opts": {"a": "Том", "b": "Негоро", "c": "Геркулес", "d": "Гарис"}, "correct": "c"}]}]$data$::jsonb) loop
    v_title := r->>'title';
    v_grade := (r->>'grade')::int;
    v_author := r->>'author';
    v_desc := format('«%s» кітабы бойынша оқу квесті. 5 сұрақ, 4 жауап нұсқасы.', v_title);

    select id into v_book_id
    from public.library_books
    where grade = v_grade
      and public.kv_norm_title(title) = public.kv_norm_title(v_title)
    order by id
    limit 1;

    -- Common Russian/Kazakh title variants from the supplied 9–10 document.
    if v_book_id is null then
      v_alias := case v_title
        when 'Я — Малала' then 'Мен — Малаламын'
        when 'Суровые дни' then 'Қаһарлы күндер'
        when 'Путешествия Гулливера' then 'Гулливердің саяхаттары'
        when 'Властелин колец: Братство кольца' then 'Сақиналар әміршісі: сақина бауырластығы'
        when 'Кочевники: заговорённый меч' then 'Көшпенділер: Алмас қылыш'
        when 'Стрела Махамбета' then 'Махамбеттің жебесі'
        when 'Как завоевать друзей и оказывать влияние на людей' then 'Дос табу және адамдарға ықпал ету өнері'
        when 'Истина и легенда' then 'Ақиқат пен аңыз'
        when 'Белый пароход' then 'Ақ кеме'
        else null end;
      if v_alias is not null then
        select id into v_book_id from public.library_books
        where grade=v_grade and public.kv_norm_title(title)=public.kv_norm_title(v_alias)
        order by id limit 1;
      end if;
    end if;

    if v_book_id is null then
      raise notice 'KITAPVERSE: library book not found — grade %, title %', v_grade, v_title;
      continue;
    end if;

    select id into v_existing from public.quests where book_id=v_book_id order by id limit 1;
    if v_existing is null then
      insert into public.quests(title,description,book_id,published)
      values(v_title,v_desc,v_book_id,true) returning id into v_quest_id;
    else
      v_quest_id:=v_existing;
      update public.quests set title=v_title, description=v_desc, published=true where id=v_quest_id;
      delete from public.quest_questions where quest_id=v_quest_id;
    end if;

    update public.library_books set quest_id=v_quest_id where id=v_book_id;

    for q in select value from jsonb_array_elements(r->'questions') loop
      insert into public.quest_questions(quest_id,sequence_no,question,option_a,option_b,option_c,option_d,correct_option)
      values(
        v_quest_id,
        (q->>'n')::int,
        q->>'question',
        q->'opts'->>'a', q->'opts'->>'b', q->'opts'->>'c', q->'opts'->>'d',
        lower(q->>'correct')
      );
    end loop;
  end loop;
end $$;

-- Clean helper after seeding (the data is already stored).
drop function if exists public.kv_norm_title(text);

